window.DATA=[{"id": "d1_thomas", "dzien": 1, "postac": "Thomas Ward, 71", "glos": "Uprzejmy, staroświecki, mówi pełnymi zdaniami i żartuje z własnej drżącej ręki.", "typ": "uczciwy-wstydliwy", "rzecz": "Lewa skórzana rękawiczka, zszyta białą nitką przy kciuku", "wnetrze": [{"sekret_id": "d1_kwit_0417", "co_widac": "W wywiniętym mankiecie tkwi kwit z tego biura, numer 0417, sprzed trzech tygodni. W księdze wydań nie ma wpisu o tym numerze: w tym miejscu jest wyrwana strona.", "co_z_tego_wynika": "Thomas już tu był i dostał coś, co nigdzie nie zapisano. Poprzednik wydawał rzeczy poza księgą."}], "wejscie": "Dobry wieczór. Thomas Ward. Zgubiłem lewą rękawiczkę mojej żony, skórzaną, w tramwaju czwórce. Ellen zmarła w lutym, a w niedzielę idę na cmentarz i nie chcę iść z jedną.", "tury": [{"pytania": [{"tekst": "Jak wygląda ta rękawiczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa skóra, rozmiar mały. Przy kciuku zszyłem ją białą nitką, bo ciemnej nie miałem. Krzywo, ale trzyma.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czwórka, wieczorny kurs do Doków. Leżała mi na kolanie i zsunęła się na zakręcie pod siedzenie.", "mina": "neutralna"}, {"tekst": "Po co wozić rękawiczki zmarłej w tramwaju?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie noszę ich na rękach. Mam je w kieszeni, jedną w drugiej, jakby ktoś mnie trzymał za rękę. Głupie, wiem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak wpisać właścicielkę w księdze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ellen Ward, przez dwa l. A mnie jako Thomas Ward, z h.", "mina": "mowi"}, {"tekst": "Czym można potwierdzić, że to właściwa rękawiczka?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Prawą mam w kieszeni. Proszę położyć obie kciukami do siebie: w prawej nitka jest czarna. Naprawiałem obie tego samego dnia.", "mina": "neutralna"}, {"tekst": "Czy to pierwsza wizyta w tym biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pierwsza. Ja się z urzędami nie zadaję, wolę kłopoty prywatne.", "mina": "klamie"}, {"tekst": "W mankiecie jest kwit z tego biura, numer 0417. Skąd?", "ton": "niewygodne", "wymaga": "d1_kwit_0417", "odpowiedz": "No dobrze. Prawą też tu zgubiłem, trzy tygodnie temu. Młody człowiek, Sam, oddał mi ją od ręki i powiedział, że wpisu nie trzeba, bo to „pamiątka, nie zguba”. Wstydziłem się, że to już drugi raz.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Zapakować w papier?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nie trzeba. Proszę podać luzem, włożę do prawej, tak jak trzeba.", "mina": "mowi"}, {"tekst": "Przy odbiorze potrzebny podpis. Może być?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Thomas Ward. Podpis mam drżący od wiosny, proszę nie brać tego za fałszerstwo.", "mina": "mowi"}, {"tekst": "Czy ktoś jeszcze może się po nią zgłosić?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Córka, Claire. Ale ona nie ma pojęcia, że zgubiłem rękawiczkę. Gdyby przyszła, proszę jej powiedzieć, że ojciec ma obie i będzie w niedzielę o jedenastej.", "mina": "neutralna"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Włożę je do jednej kieszeni, tam gdzie były.", "zysk": "Thomas idzie w niedzielę na cmentarz z obiema rękawiczkami, a w księdze pojawia się wpis 0418.", "strata": "Wydajesz na słowo i nitkę, a kwit 0417 zostaje w księdze bez wyjaśnienia.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za rękawiczkę. W niedzielę pojechałem z Claire na cmentarz, obie leżały na kamieniu przez godzinę i nikt ich nie ruszył. Claire pyta, kim jest ten młody człowiek, który wcześniej oddał mi prawą bez wpisu. Powiedziałem, że nie wiem, jak się nazywa, choć wiem. — T. Ward"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Przyjdę jutro z córką, ona ma dowód i wie, jak wygląda ta nitka.", "zysk": "Rękawiczka zostaje w biurze, dopóki ktoś nie potwierdzi tożsamości Thomasa.", "strata": "Starszy człowiek idzie do domu z jedną rękawiczką, a niedziela na cmentarzu jest zagrożona.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Claire Ward: „Ojciec dwa dni nie wychodził z domu. Proszę wydać mu tę rękawiczkę, podpiszę za niego. I proszę mi powiedzieć, kto wcześniej oddał mu prawą bez żadnego papieru.”"}}], "sprite": "rekawiczka_skora", "face": "wdowiec", "face2": null, "line": "4", "itemName": "rękawiczka", "inside": {"img": "W1", "x": 0.2, "y": 0.72}}, {"id": "d1_rosa", "dzien": 1, "postac": "Rosa Vale, 33", "glos": "Zmęczona, praktyczna, liczy na głos. Suchy humor, krótkie zdania.", "typ": "uczciwy", "rzecz": "Brązowa koperta z wypłatą, jedna zszywka", "wnetrze": [{"sekret_id": "d1_lista_nocy", "co_widac": "W kopercie jest 129 dolarów i kartka z listą nocy: trzy odhaczone, czwarta przekreślona. Na odcinku zbiorczym stoi nazwisko I. Bell.", "co_z_tego_wynika": "Wypłatę odbierała i rozdzielała Iris Bell. Czwartą noc Rosy wykreśliła Iris."}], "wejscie": "Dobry wieczór. Rosa Vale, pracuję w pralni pod estakadą. Zgubiłam kopertę z wypłatą, 129 dolarów, w jedenastce. Czynsz mam jutro, więc ta koperta to cały mój tydzień.", "tury": [{"pytania": [{"tekst": "Jak wygląda koperta?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowa, jedna zszywka. Zszywka w połowie weszła, bo kierownik zszywał na stojąco.", "mina": "mowi"}, {"tekst": "Gdzie i o której została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, szósta rano. Położyłam kopertę obok, żeby zapiąć torbę, i zasnęłam do pętli.", "mina": "neutralna"}, {"tekst": "Skąd pewność, że było tam 129 dolarów?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo liczę na sucho: trzy noce po 43. Sto dwadzieścia dziewięć. Jak coś się nie zgadza, to ja się zgadzam.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Kto wypłacił tę kopertę?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Iris Bell, zarządczyni naszej kamienicy. Odbiera zbiorową wypłatę z pralni i rozdaje nam w domu. Dała mi kopertę w tramwaju, bo wysiadała.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w środku, poza pieniędzmi?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kartka z naszymi nocami. Nic ważnego.", "mina": "neutralna"}, {"tekst": "Dlaczego wypłatę odbiera ktoś inny niż pracownicy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo tak jest wygodnie. Dla niej. Dla nas byłoby wygodnie dostać pieniądze do ręki, ale to jej układ i nie pytam.", "mina": "neutralna"}, {"tekst": "Na liście jedna noc jest przekreślona. Czemu?", "ton": "niewygodne", "wymaga": "d1_lista_nocy", "odpowiedz": "Bo w czwartek wyszłam o północy, córka miała gorączkę. Iris wykreśliła całą noc, nie połowę. Czterdzieści trzy dolary za cztery godziny. Wolałabym nie rozmawiać o tym.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Potrzebna torba na pieniądze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nie, kieszeń. Przy dwustu dolarach bym myślała, przy stu dwudziestu dziewięciu liczę w głowie.", "mina": "mowi"}, {"tekst": "Podpisze odbiór po przeliczeniu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Podpiszę. Rosa Vale, przez V. Przeliczę przy szybie, żeby nie było pytań.", "mina": "mowi"}, {"tekst": "Co będzie, jeśli wypłata nie wróci dziś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Czynsz ze spóźnieniem i dwadzieścia dolarów kary u zarządczyni. Czyli u Iris. Sto dziewięć dolarów zamiast stu dwudziestu dziewięciu.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Policzę przy szybie. Sto dwadzieścia dziewięć. Dziękuję, serio.", "zysk": "Rosa ma czynsz, a w księdze jest jej podpis pod kwotą 129 dolarów.", "strata": "Odcinek zbiorczy jest wystawiony na Iris Bell, więc w papierach wypłata trafia do innej osoby niż ta, którą wskazuje odcinek.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Iris zeszła do pralni i spytała, kto mi pozwolił odbierać pieniądze przez okienko. Powiedziałam, że nikt, że sama się zgubiłam. Od przyszłego tygodnia odbieram wypłatę osobiście, a nie przez nią. — Rosa"}}, {"akcja": "odmow", "reakcja": "Dobrze, powiedzcie Iris. Poczekam, tylko czynsz nie poczeka.", "zysk": "Koperta wraca do osoby wskazanej na odcinku wypłaty, zgodnie z przepisem.", "strata": "Rosa płaci dwadzieścia dolarów kary za spóźniony czynsz.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Iris oddała mi kopertę, ale z potrąceniem: sto dziewięć dolarów. Dwadzieścia za spóźniony czynsz, który sama pobiera. Powiedziała, że to formalność. Żałuję, że nie zasnęłam na stojąco. — Rosa"}}], "sprite": "koperta", "face": null, "face2": null, "line": "11", "itemName": "koperta", "inside": {"img": "W20", "x": 0.51, "y": 0.58}}, {"id": "d2_jonah", "dzien": 2, "postac": "Jonah Kerr, 24", "glos": "Gada szybko, poprawia się w pół zdania. Kiedy pada imię June, zwalnia.", "typ": "uczciwy-wstydliwy", "rzecz": "Czarny plecak z pękniętą klamrą", "wnetrze": [{"sekret_id": "d2_kartka_june", "co_widac": "W pudełku jest pierścionek, paragon na 240 dolarów i kartka: „Nie zrobię ci tego, że powiem tak. Oddaj go. J.” Zwrot do sklepu jest możliwy tylko z paragonem i tylko do dziewiątej.", "co_z_tego_wynika": "June znalazła pierścionek i odmówiła, zanim usłyszała pytanie. Jonah potrzebuje plecaka, żeby odzyskać pieniądze."}], "wejscie": "Cześć, Jonah. Zgubiłem plecak w jedenastce, czarny, z pękniętą klamrą. Muszę go mieć przed dziewiątą, bo w środku jest rzecz, którą trzeba oddać do sklepu.", "tury": [{"pytania": [{"tekst": "Co jest w głównej komorze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ładowarka, książka, puszka po coli. I bilety, dużo biletów, nie wiem, czemu je zbieram.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie plecak został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, wczoraj wieczorem, pod składanym siedzeniem przy drzwiach. Wcisnąłem go nogą, żeby June miała gdzie stanąć.", "mina": "mowi"}, {"tekst": "Dlaczego to takie pilne?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo w kieszeni przy plecach jest rzecz do zwrotu. Sklep, dziewiąta, tylko dziś. Więcej nie powiem, to prywatne.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kim jest June?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Moja dziewczyna. Znaczy była. Znaczy jest. Dzisiaj jest niejasno.", "mina": "emocja"}, {"tekst": "Do jakiego sklepu zwrot?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jubiler Halloran na Rynku. Dziewiąta rano i tylko z oryginalnym paragonem.", "mina": "mowi"}, {"tekst": "Dlaczego ktoś zwraca do sklepu coś, co kupił?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kupiłem za drogo. Zmieniłem zdanie. Zdarza się.", "mina": "klamie"}, {"tekst": "W pudełku jest kartka podpisana J. Czytać?", "ton": "niewygodne", "wymaga": "d2_kartka_june", "odpowiedz": "...Dawaj. „Nie zrobię ci tego, że powiem tak. Oddaj go.” No. Znalazła pudełko w poniedziałek i ani słowa. Tylko to. Dobra. Oddam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dasz radę dotrzeć na dziewiątą?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Rynek jest dwa przystanki od pętli. Zdążę nawet na piechotę, jeśli nie zatrzymam się przy żadnej cukierni.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jonah Kerr, K i dwa r. Czytelnie, bo sklep porównuje podpis na rewersie paragonu.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli sklep nie przyjmie zwrotu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dwieście czterdzieści dolarów na raty do czerwca. Dwa razy więcej dostaw, mniej snu. Jak wszyscy.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki. Serio. Lecę, zanim się rozmyślę.", "zysk": "Jonah zdąży do sklepu i odzyska 240 dolarów, bez rat do czerwca.", "strata": "Plecak z kartką od June wychodzi z biura bez wpisu, bo Jonah prosi o dyskrecję.", "echo": {"za_dni": 3, "forma": "list", "tekst": "To Jonah. Oddałem pierścionek, odzyskałem 240 dolarów i kartkę trzymam w portfelu. June odpisała mi jedno słowo: „Dzięki.” Nie wiem, czy to dobrze. Plecak ma nową klamrę."}}, {"akcja": "odmow", "reakcja": "Co? Ale to MÓJ plecak! Dobrze, dobrze, przyjdę z paragonem z plecaka.", "zysk": "Plecak zostaje w biurze do czasu dowodu własności.", "strata": "Jonah nie zdąży do sklepu: 240 dolarów zostaje na ratach do czerwca.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Sklep zamknął się na zwrocie. Pierścionek mam, 240 dolarów nie mam. June kupiła sobie kota, wysłała zdjęcie. Plecak odbiorę w poniedziałek, jak mi się nie odechce. — Jonah"}}], "sprite": "plecak", "face": "chlopak", "face2": null, "line": "11", "itemName": "plecak", "inside": null}, {"id": "d2_hana", "dzien": 2, "postac": "Hana Moreau, 26", "glos": "Precyzyjna i spięta, mówi gotowymi zdaniami jak z programu koncertu. Przy kłamstwie wyraźnie akcentuje każdą sylabę.", "typ": "opowieść wzruszająca", "rzecz": "Czarny sztywny futerał na skrzypce z zieloną naklejką", "wnetrze": [{"sekret_id": "d2_etykieta_wyp", "co_widac": "Pod pokrywą futerału przyklejona kartka: „Własność Konserwatorium. Wypożyczone H. Moreau do 14 października.” Dzisiejsza data jest o dzień późniejsza.", "co_z_tego_wynika": "Skrzypce nie są Hany. Jej wypożyczenie wygasło wczoraj."}], "wejscie": "Dobry wieczór. Hana Moreau, skrzypaczka. Zgubiłam futerał ze skrzypcami w czwórce. O ósmej rano mam pierwszy koncert z orkiestrą zawodową, bez tego instrumentu nie wyjdę na scenę.", "tury": [{"pytania": [{"tekst": "Jak wygląda futerał?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, sztywny, zamki mosiężne. Wewnątrz wieka zielona naklejka konserwatorium, a rączka owinięta czerwoną taśmą.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czwórka, ostatni kurs. Postawiłam go między nogami, zadzwoniła mama i wysiadłam bez futerału.", "mina": "neutralna"}, {"tekst": "Czyje to są skrzypce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Moje. Oczywiście, że moje. Gram na nich od siedmiu lat.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co jeszcze jest w futerale oprócz skrzypiec?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kalafonia, jedwabna szmatka, nuty Mendelssohna z moimi zapiskami ołówkiem. Wszystko, co potrzebne.", "mina": "mowi"}, {"tekst": "Czy w skrzypcach jest etykieta lutnika?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jest, ale mała. Nazwiska nie pamiętam, od lat nie zaglądałam do środka.", "mina": "neutralna"}, {"tekst": "Dlaczego to takie pilne właśnie dziś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo dziś jest koncert. Dostałam się z listy rezerwowej. Nikt nie zagra za mnie, nie ma drugiej takiej szansy.", "mina": "emocja"}, {"tekst": "Pod pokrywą jest kartka: wypożyczenie do 14 października. Co to znaczy?", "ton": "niewygodne", "wymaga": "d2_etykieta_wyp", "odpowiedz": "Do wczoraj. Tak. Konserwatorium nie przedłużyło, bo komisja zbiera się w poniedziałek. Nie jestem złodziejką, jestem po prostu o dwa dni spóźniona. Ale gram dziś.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Daleko stąd do filharmonii?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Cztery przystanki. Próba o siódmej. Jeśli wyjdę stąd przed szóstą, zdążę rozgrzać palce.", "mina": "mowi"}, {"tekst": "Podpisze odbiór instrumentu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Hana Moreau. Napiszę czytelnie, ręka drży mi od wczoraj.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli skrzypce wrócą do konserwatorium?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy mój pierwszy koncert zagra ktoś inny z listy. Mnie wykreślą, bo nie mam instrumentu.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. W poniedziałek pójdę do komisji, obiecuję. Najpierw zagram.", "zysk": "Koncert o ósmej rano odbędzie się z Haną na scenie.", "strata": "Wydajesz instrument należący do konserwatorium osobie, której wypożyczenie wygasło wczoraj.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zagrałam. Nikt nie wiedział, że skrzypce są po terminie. W poniedziałek komisja przedłużyła mi wypożyczenie do końca roku. Napisali w protokole, że instrument został „odnaleziony w biurze rzeczy znalezionych”. Przepraszam za zamieszanie. — H. Moreau"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Skrzypce są konserwatorium, to prawda. Proszę im powiedzieć, że byłam tu pierwsza.", "zysk": "Skrzypce wracają do właściciela, czyli do konserwatorium, zgodnie z etykietą.", "strata": "Hana traci pierwszy koncert z orkiestrą zawodową.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Kuratorka z konserwatorium odebrała skrzypce i podziękowała za sumienność. Na koncercie zagrał ktoś inny z listy. Ja gram teraz na altówce koleżanki w piwnicy. Nie mam żalu, tylko dyplom. — H. Moreau"}}], "sprite": "futeral", "face": null, "face2": null, "line": "6", "itemName": "futerał na skrzypce", "inside": null}, {"id": "d3_maz_i_siostra", "dzien": 3, "postac": "Evan Doyle, 37", "glos": "Evan: grzecznie, pełnymi zdaniami, pod presją wraca do tego samego pytania. Lena: szybko, urywa, mówi za dużo.", "typ": "kłamca i prawdomówna", "rzecz": "Czarny telefon w skórzanym etui z odklejonym rogiem", "ludzie": {"maz": "Evan", "siostra": "Lena"}, "wnetrze": [{"sekret_id": "d3_telefon_wiadomosc", "co_widac": "Na ekranie blokady wisi wiadomość od „Lena” z czwartku, 23:48: „Nie wracaj do domu. Jadę po ciebie w sobotę.” Pod etui złożone stare zdjęcie dwóch dziewczynek z podpisem „Maya i Lena”.", "co_z_tego_wynika": "Telefon należy do Mai. Siostra kazała jej nie wracać do męża. Maya zostawiła telefon celowo."}], "wejscie": "Dobry wieczór. Evan Doyle. Moja żona Maya zaginęła w czwartek, a jej telefon został w jedenastce. Czy mógłbym prosić o jego wydanie? W środku mogą być wiadomości, które pomogą policji.", "tury": [{"pytania": [{"tekst": "Jak wygląda ten telefon?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, w skórzanym etui, róg odklejony. Maya trzymała go zawsze ekranem do dołu. Nigdy nie pytałem dlaczego.", "kto": "maz", "mina": "mowi"}, {"tekst": "Od kiedy Maya nie wraca do domu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Od czwartku wieczorem. W piątek o szóstej dziesięć zgłosiłem zaginięcie na komisariacie.", "kto": "maz", "mina": "neutralna"}, {"tekst": "Czy coś mogło skłonić Maję do odejścia?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nic. Dwa tygodnie temu byliśmy nad jeziorem i wszystko było w porządku. Nie było żadnej kłótni, nie było nic.", "kto": "maz", "mina": "klamie"}, {"tekst": "Szalik z inicjałami M.D. leży w biurze od wczoraj. Zostawiony celowo?", "ton": "niewygodne", "wymaga": "d2_szalik_md", "odpowiedz": "Szalik? Dałem jej go na rocznicę. Nigdy go nie zdejmowała. Jeśli go zostawiła, to znaczy, że nie planowała wracać. Albo że chciała, żebym wiedział.", "kto": "maz", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ktoś jeszcze czeka za Evanem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Ja. Lena Brandt, siostra Mai. Evan nie zauważył mnie przez godzinę, bo stoi do mnie plecami od czwartku.", "kto": "siostra", "mina": "emocja"}, {"tekst": "Dlaczego oboje chcecie tego samego telefonu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo ja wiem, co jest na ekranie, a on chciałby, żeby nikt nie wiedział. No, nic. Nic nie powiedziałam.", "kto": "siostra", "mina": "emocja"}, {"tekst": "Evan, czy Maya mówiła kiedyś o odejściu?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Znaczy kłóciliśmy się, jak każdy, ale o odejściu nie. W czwartek rano jeszcze jedliśmy razem śniadanie, o siódmej piętnaście.", "kto": "maz", "mina": "klamie"}, {"tekst": "Na ekranie blokady jest wiadomość: „Nie wracaj do domu.” Czyja?", "ton": "niewygodne", "wymaga": "d3_telefon_wiadomosc", "odpowiedz": "Moja. Napisałam ją w czwartek o 23:48. Maya prosiła mnie, żebym była w gotowości, ale nie pytała, co mam zrobić. Evan, nie krzycz, to był jej wybór, nie twój.", "kto": "siostra", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy ktoś ma kontakt do Mai?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nie twoja sprawa, Evan. Maya wie, że jestem pod telefonem, tyle ci powiem.", "kto": "siostra", "mina": "neutralna"}, {"tekst": "Czy ktoś ma od Mai upoważnienie do odbioru?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jestem jej mężem i mam akt ślubu w domu. Przyniosę go jutro, jeśli to konieczne.", "kto": "maz", "mina": "mowi"}, {"tekst": "Komu Maya zaufałaby bardziej?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Mnie. Bo ja wiem, od czego ona... od czego jest zmęczona. Chodzi mi o pracę. O pracę.", "kto": "siostra", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj_evan", "etykieta": "Wydaj Evanowi (mąż, akt ślubu jutro)", "kto": "maz", "reakcja": "Dziękuję. Akt ślubu przyniosę w poniedziałek, obiecuję.", "zysk": "Evan dostaje telefon i ma szansę szybko zamknąć sprawę z policją.", "strata": "Maya traci telefon, który zostawiła celowo, a Lena traci zaufanie do biura.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Wiem, że oddano telefon Evanowi. Zadzwonił do mnie z numeru Mai i powiedział, że przeczytał moją wiadomość. Nie rozmawiam już z wami o niczym. — Lena Brandt"}}, {"akcja": "wydaj_lena", "etykieta": "Wydaj Lenie (siostra)", "kto": "siostra", "reakcja": "Dziękuję. Zaniosę go. Evan, nie patrz tak.", "zysk": "Telefon trafia do osoby, która zna Maję i wie, co z nim zrobić.", "strata": "Evan odchodzi bez niczego i uzna, że biuro stoi po stronie jej rodziny.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zgłaszam pismo: poprosiłem o wydanie telefonu mojej żony, a biuro oddało go osobie trzeciej. Kopia trafi do policji i do inspekcji. — Evan Doyle"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj telefon do czasu zgłoszenia Mai", "kto": "siostra", "reakcja": "Zostawcie go tu. Jeśli Maya po niego przyjdzie, tylko ona go dostanie.", "zysk": "Telefon czeka na Maję, a nikt z rodziny nie pozna jej wiadomości przed nią.", "strata": "Evan odchodzi z pustymi rękami i uznaje, że biuro blokuje poszukiwania żony.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Telefon został u was, Evan wrócił do domu bez niego. W środę ktoś wsunął mi pod drzwi kartkę: „Dziękuję, że nie oddaliście.” Bez podpisu. Znam to pismo i nie powiem czyje. — Lena"}}], "sprite": "telefon", "face": "maz", "face2": {"maz": "maz", "siostra": "siostra"}, "line": "11", "itemName": "telefon", "inside": null}, {"id": "d3_dex", "dzien": 3, "postac": "Dex Harlan, 38", "glos": "Gładki handlarz: „no popatrz”, „wiesz”, „dobra”. Zawsze trochę za szybko przechodzi do pieniędzy.", "typ": "zgadywacz i łapówka", "rzecz": "Nakręcany budzik w porysowanej metalowej obudowie", "wnetrze": [{"sekret_id": "d3_budzik_kartka", "co_widac": "Pod tylną klapką tkwi kartka: „Lou, klucz przekręcaj tylko do oporu. Dzwonek od jutra ustawiasz sam. — Mama”. Wskazówka alarmu stoi na 5:40.", "co_z_tego_wynika": "Budzik należy do Lou, która jutro zaczyna pierwszą zmianę. Dex nie zna ani kartki, ani godziny."}], "wejscie": "Cześć, Dex. Zgubiłem budzik w szóstce, taki metalowy, nakręcany. Wartość sentymentalna, no popatrz. Dam coś na kawę, jak pójdzie szybko.", "tury": [{"pytania": [{"tekst": "Jak wygląda budzik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "No budzik. Metalowy, porysowany, ze wskazówkami. Taki zwyczajny, wiesz, jak każdy.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, wczoraj wieczorem. Siedziałem na końcu, wysiadłem przy Rynku, wiesz, jak to jest.", "mina": "neutralna"}, {"tekst": "Czemu budzik jest wart dwudziestu dolarów na kawę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo się śpieszę, mam spotkanie. Dwadzieścia dolców dla ciebie i jesteśmy kwita, dobra?", "mina": "mowi"}]}, {"pytania": [{"tekst": "Ma jakieś znaki szczególne?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Znaki? Ma klucz z tyłu do nakręcania. No jak to budzik.", "mina": "neutralna"}, {"tekst": "Na którą ustawiony jest alarm?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na piątą trzydzieści. Zawsze na tę, od lat.", "mina": "klamie"}, {"tekst": "Skąd masz ten budzik?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Dostałem od mamy. Znaczy od taty. Od kogoś z rodziny, nie rób z tego przesłuchania.", "mina": "neutralna"}, {"tekst": "Pod tylną klapką jest kartka podpisana „Mama”. Co na niej jest?", "ton": "niewygodne", "wymaga": "d3_budzik_kartka", "odpowiedz": "Kartka? A, ta kartka. Życzenia pewnie. No dobra, dwadzieścia dolców i nie robimy z tego sprawy.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Co zrobisz z budzikiem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Postawię na półce i będę patrzył. Poważnie. Co, nie wierzysz?", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór nazwiskiem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Dex Harlan. Z jednym l i jedną miną.", "mina": "neutralna"}, {"tekst": "Czy ktoś inny mógłby się upomnieć o ten budzik?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Skąd. Czemu miałby się ktoś upominać o budzik? Nikt, nikt, sprawa jasna.", "mina": "klamie"}]}], "decyzje": [{"akcja": "wydaj", "kasa": 20, "reakcja": "Miło się współpracuje. Kawa na mnie, jak będę przejeżdżał.", "zysk": "Dostajesz 20 dolarów poza księgą i kolejka robi się krótsza.", "strata": "Budzik wychodzi do niewłaściwej osoby, bo Dex nie zna ani kartki, ani godziny alarmu.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Piszę do biura. Budzik z kartką od mamy wydano facetowi, który nie wiedział, co jest pod klapką. Spóźniłam się na pierwszą zmianę w zajezdni o szóstej. Mama pyta, gdzie jest budzik. Nie wiem, co jej powiedzieć. — Lou"}}, {"akcja": "odmow", "reakcja": "No dobra. Wiesz, kawa była uczciwa.", "zysk": "Budzik zostaje w biurze do zgłoszenia prawdziwej właścicielki.", "strata": "Nie dostajesz 20 dolarów, a Dex wróci z inną historią.", "echo": {"za_dni": 1, "forma": "gosc", "tekst": "Lou, 19, uczennica zajezdni: „Jakiś facet zaczepił mnie na przystanku i pytał o budzik. To mój, od mamy, z kartką pod klapką. Jutro o szóstej mam pierwszą zmianę.”"}}], "sprite": "budzik", "face": null, "face2": null, "line": "6", "itemName": "budzik", "inside": null}, {"id": "d4_iris", "dzien": 4, "postac": "Iris Bell, 56", "glos": "Cicho, uprzejmie, ze zdrobnieniami. Każdą prośbę nazywa drobną przysługą, a groźbę podaje jak prognozę pogody.", "typ": "presja i łapówka", "rzecz": "Płaska paczka w szarym płótnie, przewiązana sznurkiem", "wnetrze": [{"sekret_id": "d4_blankiet_kasetka", "co_widac": "Pod płótnem leży kasetka na kłódkę, przez szparę widać brzeg paszportu z wyciętą stroną. Przy kasetce blankiet z numerem odbioru, dopisek „dla nocnej zmiany, bez wpisu” i pieczątka kontroli.", "co_z_tego_wynika": "To nie są papiery lokatorów, tylko dokumenty dla kogoś, kto chce zniknąć. Poprzednik przyjmował takie paczki bez wpisu."}], "wejscie": "Dobry wieczór. Iris Bell, zarządzam kamienicą przy Cooper Street dziewięć. Zgubiła mi się paczka w szarym płótnie, szóstka, ostatni kurs. To drobiazg, ale lokatorzy czekają na to do rana.", "tury": [{"pytania": [{"tekst": "Jak wygląda paczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Płaska, szare płótno, związana sznurkiem. W środku niewielka kasetka na kłódkę. Nic wartościowego, ale lokatorzy się niecierpliwią.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, ostatni kurs, na półce nad siedzeniem. Zawsze tak robię i zawsze pamiętam. Wczoraj nie.", "mina": "neutralna"}, {"tekst": "Co jest w kasetce?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Papiery lokatorów. Pokwitowania, drobne rozliczenia. Nic, co by kogokolwiek zainteresowało.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Kim są lokatorzy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwadzieścia rodzin z kamienicy. Zbieram od nich zaliczki na remont i trzymam ich dokumenty, żeby się nie zgubiły. Ironia, prawda?", "mina": "mowi"}, {"tekst": "Czy w paczce jest numer odbioru?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Blankiet z numerem leży na wierzchu. Można sprawdzić, jeśli to konieczne. Ale po co psuć pakunek.", "mina": "mowi"}, {"tekst": "Czemu paczka jedzie tramwajem, a nie pocztą?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo lokatorzy odbierają o różnych godzinach. Tramwaj to najtańszy goniec. A te biura mają poczucie obowiązku.", "mina": "neutralna"}, {"tekst": "Blankiet jest zaadresowany do nocnej zmiany, bez wpisu. Co to znaczy?", "ton": "niewygodne", "wymaga": "d4_blankiet_kasetka", "odpowiedz": "Ach. To drobiazg, umowa z poprzednim pracownikiem. On wiedział, jak z tym postępować. Ja jestem przyzwyczajona do ludzi, którzy wiedzą.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy to pilne?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Najlepiej dziś. Nie lubię naciskać, ale lokatorzy lubią spać spokojnie.", "mina": "mowi"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Oczywiście, Iris Bell. I chciałabym zostawić drobną kopertę za fatygę. Nie jako opłatę, jako wyraz uznania. Dwieście dolarów.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli wydanie nastąpi tylko z wpisem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy poczekam do rana. A rano zajmą się mną inni, mniej cierpliwi. Nie mówię tego jak groźbę, tylko jak prognozę pogody.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "etykieta": "Wydaj paczkę i zapisz w księdze", "reakcja": "Dziękuję. Pełny wpis, jak widzę. Bardzo oficjalnie, ale dobrze.", "zysk": "Księga jest czysta: paczka wpisana jako znaleziona i wydana Iris Bell.", "strata": "Iris traci poczucie, że ma w biurze swojego człowieka.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Paczka dotarła. Dziękuję za pełny wpis. Mój poprzedni współpracownik nie był tak skrupulatny, może to i lepiej. Ja jednak lubię wiedzieć, z kim pracuję. — I. Bell"}}, {"akcja": "wydaj_cicho", "etykieta": "Wydaj i przyjmij kopertę (bez wpisu)", "kasa": 200, "reakcja": "Miło. Rozumiemy się bez zbędnych słów.", "zysk": "Dostajesz 200 dolarów, czyli więcej niż tygodniowy czynsz.", "strata": "Paczka wychodzi bez wpisu, jak za czasów poprzednika, a Ty jesteś teraz w jej układzie.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za dyskrecję. W przyszłym tygodniu przyniosę jeszcze jedną paczuszkę. Będzie bardzo drobna. — I. Bell"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj paczkę w depozycie kontrolnym", "reakcja": "Rozumiem. Takie jest prawo, nie przeczę. Proszę tylko zapisać, że miałam dobre intencje.", "zysk": "Paczka leży w depozycie: nikt jej nie dostaje i nikt nie może zarzucić Ci układu.", "strata": "Iris traci cierpliwość, a lokatorzy czekają na dokumenty. Prognoza pogody się spełnia.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Iris Bell: „Rano zgłosiło się do mnie dwóch lokatorów z pytaniem, gdzie są ich dokumenty. Powiedziałam, że biuro zatrzymało je z uwagi na procedurę. Nie byli zadowoleni.”"}}], "sprite": "paczka_plotno", "face": "dama", "face2": null, "line": "6", "itemName": "paczka w płótnie", "inside": {"img": "W2", "x": 0.66, "y": 0.35}}, {"id": "d4_gus", "dzien": 4, "postac": "Gus Pell, 55", "glos": "Ściszony, grzeczny ze strachu, rozgląda się. Zaczyna zdania od „tylko”.", "typ": "uczciwy-wstydliwy i łapówka", "rzecz": "Brązowy, wytarty portfel na zatrzask", "wnetrze": [{"sekret_id": "d4_dwa_dowody", "co_widac": "W portfelu są dwa dowody osobiste: Gustaw Pell i August Ferro, z tym samym zdjęciem. Do tego zdjęcie dziewczynki i bilet w jedną stronę, z datą na niedzielę.", "co_z_tego_wynika": "Gus ma dwie tożsamości i planuje wyjazd. Prawdopodobnie jest klientem Skrytki."}], "wejscie": "Dobry wieczór. Wiem, jak wyglądam: szlafrok pod płaszczem, bo wyszedłem z domu w pośpiechu. Zgubiłem portfel w jedenastce, brązowy, wytarty. Potrzebuję go natychmiast, jest w nim wszystko, co mam.", "tury": [{"pytania": [{"tekst": "Jak wygląda portfel?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Brązowy, wytarty, na zatrzask. Mam go od jedenastu lat, wygiął się na moją pupę. Przepraszam.", "mina": "mowi"}, {"tekst": "Co w nim jest?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Prawo jazdy. Dwadzieścia dolarów. Zdjęcie córki. Nic więcej, tylko tyle.", "mina": "klamie"}, {"tekst": "Dlaczego szlafrok o pierwszej w nocy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wyszedłem z domu bez myślenia. Kłótnia z żoną. Nic poważnego, tylko poważnie. W tym szlafroku zyskuję tylko na wiarygodności.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Jak się nazywasz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gustaw Pell. Dla znajomych Gus. Tylko proszę nie zapisywać, że byłem w szlafroku.", "mina": "mowi"}, {"tekst": "Gdzie mieszkasz?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mill Street dwanaście. Zaraz, nie, piętnaście. Dwanaście to brat. Tylko że brat się wyprowadził.", "mina": "klamie"}, {"tekst": "Z kim się pokłóciłeś?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z żoną. Nie, z teściową. Z obiema. Tylko że o rodzinie nie rozmawiajmy, dobrze?", "mina": "neutralna"}, {"tekst": "W portfelu są dwa dowody: Pell i Ferro. Który jest Twój?", "ton": "niewygodne", "wymaga": "d4_dwa_dowody", "odpowiedz": "Dwa? To się da wytłumaczyć. Jeden po dziadku. Który mój, tego nie powiem, bo z tego źle się kończy. Dwadzieścia dolarów i zapominamy.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dokąd teraz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Do domu. Przebiorę się i... do pracy. Jest sprawa. Tylko jak najszybciej.", "mina": "neutralna"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Podpiszę. G. Samo G. Wystarczy, tak? Tylko żeby nie było pytań o resztę.", "mina": "neutralna"}, {"tekst": "Co będzie, jeśli portfel zostanie w biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy ktoś pomyśli, że zniknąłem. I w pewnym sensie będzie miał rację.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Zapomnijmy, że byłem w szlafroku.", "zysk": "Gus odchodzi z portfelem i dwoma tożsamościami w kieszeni.", "strata": "Nie sprawdzasz, który dowód jest prawdziwy, a w księdze zostaje tylko wpis „Pell”.", "echo": {"za_dni": 4, "forma": "list", "tekst": "Pocztówka z miasta, którego nazwy nie znam: „Dziękuję za portfel. Pell już nie istnieje. — G.”"}}, {"akcja": "odmow", "reakcja": "Rozumiem. Wrócę z kimś, kto ma wszystkie dokumenty. Tylko proszę nie dzwonić nigdzie.", "zysk": "Portfel zostaje w biurze razem z dwoma dowodami.", "strata": "Gus wraca do domu w szlafroku, a jego sprawa jest otwarta.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Do biura zadzwoniła żona Gusa Pella: mąż zniknął od środy, zostawił tylko szlafrok i trzy dolary. Pyta, czy ktoś go widział. Zapisano: brak informacji."}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń po dyżurnego policjanta", "reakcja": "Proszę, bez policji. To nie jest sprawa dla policji.", "zysk": "Dyżurny przyjmie zgłoszenie, a oba dowody trafią do protokołu.", "strata": "Gus ucieknie, zanim ktoś przyjdzie, i w protokole zostanie pusta rubryka „właściciel”.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Z komisariatu: portfel z dwoma dowodami wpisano do ewidencji, właściciel się nie zgłosił. Dziękujemy za czujność. — N. Reyes"}}], "sprite": "portfel", "face": null, "face2": null, "line": "11", "itemName": "portfel", "inside": null}, {"id": "d5_noah", "dzien": 5, "postac": "Noah Reyes, 42", "glos": "Spokojny, powtarza własnymi słowami to, co usłyszał, i prosi o potwierdzenie jednego szczegółu: „Czyli: …, dobrze rozumiem?”", "typ": "uczciwy, pomija", "rzecz": "Czarny służbowy notes na spirali, wgnieciony z lewej strony", "wnetrze": [{"sekret_id": "d5_notes_ulotki", "co_widac": "Na stronie z nagłówkiem „Doyle, E.”: „zgłoszenie pt 6:10, zeznaje: zniknęła w nocy”. Niżej ołówkiem: „ulotki z jej zdjęciem zamówione w czwartek o 22:15 w kopiarni na Rynku, sprawdzić”.", "co_z_tego_wynika": "Evan zamówił ulotki z twarzą żony na kilka godzin przed jej zniknięciem. Noah to wie i nie ma dowodu."}], "wejscie": "Dobry wieczór. Noah Reyes, policja. Zgubiłem służbowy notes, czarny, na spirali. Są w nim notatki ze sprawy zaginięcia Mai Doyle, a bez nich nie złożę rano raportu. Czy telefon zaginionej trafił do biura?", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Dobry wieczór. Noah Reyes, policja. Zgubiłem służbowy notes ze sprawy Mai Doyle, czarny, na spirali. Doyle mówi, że odebrał tu telefon żony. Chcę wiedzieć, kto go wydał i na jakiej podstawie.", "d3_maz_i_siostra:wydaj_lena": "Dobry wieczór. Noah Reyes, policja. Zgubiłem służbowy notes ze sprawy Mai Doyle, czarny, na spirali. Doyle złożył skargę, że telefon jego żony oddano siostrze. Chcę wiedzieć, kto i dlaczego.", "d3_maz_i_siostra:zatrzymaj": "Dobry wieczór. Noah Reyes, policja. Zgubiłem służbowy notes ze sprawy Mai Doyle, czarny, na spirali. Doyle skarży się, że biuro zatrzymało telefon żony. Dobrze, że nie oddało, ale muszę wiedzieć dlaczego."}, "tury": [{"pytania": [{"tekst": "Jak wygląda notes?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarny, na spirali, okładka wgnieciona z lewej strony. Z tyłu wklejony bilet na pociąg do brata, którego nie odwiedzam.", "mina": "mowi"}, {"tekst": "Gdzie został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, kurs o piątej rano. Położyłem go na półce, żeby wyjąć mokrą rękę z kieszeni. Wysiadłem przy komisariacie bez notesu.", "mina": "neutralna"}, {"tekst": "Co dokładnie jest w notatkach o Doyle'ach?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zeznanie męża, godzina zgłoszenia i kilka pytań, na które nie mam odpowiedzi. Nic, co by komuś pomogło poza mną.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Kim jest Maya Doyle?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Trzydzieści cztery lata, elektryczka, mąż Evan. W piątek rano mąż zgłosił zaginięcie. Od tamtej pory nikt jej nie widział.", "mina": "mowi"}, {"tekst": "Czy to wygląda na przestępstwo?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na razie na zaginięcie. Dorosła kobieta może zniknąć, jeśli chce. Ale muszę sprawdzić, czy chce.", "mina": "mowi"}, {"tekst": "Czy Evan Doyle mówi prawdę?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Mówię, co słyszałem: że zniknęła w nocy, a zgłosił o szóstej dziesięć. Jedna rzecz mi się nie zgadza, ale to moje zmartwienie.", "mina": "neutralna"}, {"tekst": "W notesie jest zapis o ulotkach zamówionych w czwartek o 22:15. Co to znaczy?", "ton": "niewygodne", "wymaga": "d5_notes_ulotki", "odpowiedz": "Że ktoś wydrukował plakaty z twarzą Mai, zanim zgłosił, że zniknęła. Sprawdzałem to wczoraj, kopiarnia na Rynku ma rachunek. Nie mam dowodu, że to krętactwo. Proszę o tym nie mówić Doyle'owi.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy Maya jest w niebezpieczeństwie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nie wiem. Jeśli wyszła sama, to nie. Jeśli ktoś ją do tego zmusił, to tak. Dlatego potrzebuję notesu.", "mina": "mowi"}, {"tekst": "Potwierdzi odbiór notesu?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Noah Reyes, odznaka cztery-zero-siedem. Legitymację też mam w notesie, więc proszę się nie dziwić, że nie pokazuję.", "mina": "neutralna"}, {"tekst": "Czy będzie więcej wizyt w sprawie Mai?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pewnie tak. Rzeczy zaginionej wracają tramwajami. Ktoś zostawia je po kolei, a ja mam pytania do każdego, kto po nie przyjdzie.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Dopisuję: biuro zwróciło notes w stanie nienaruszonym.", "zysk": "Noah ma notatki i zapamięta, że biuro współpracuje.", "strata": "Podpisujesz zdanie „nienaruszony”, nawet jeśli notes był otwarty, i oddajesz zapis, którego nie kontrolujesz.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Doyle zeznał dziś, że był w kopiarni „w innej sprawie”. Sprawa otwarta. Jeśli ktoś zapyta o ulotki, biuro nie wie nic. — N. Reyes"}}, {"akcja": "odmow", "etykieta": "Odmów: najpierw legitymacja", "reakcja": "Rozumiem. Zadzwonię z komisariatu, ktoś przyniesie papier.", "zysk": "Procedura zachowana: notes nie wychodzi bez potwierdzenia tożsamości.", "strata": "Noah traci pół nocy, a notes z jego wątpliwościami leży na ladzie, gdzie każdy stojący za nim może go zobaczyć.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Noah Reyes: „Dostałem notes z komisariatu o świcie, kolejka była dłuższa niż u was. Następnym razem zapiszę legitymację osobno.”"}}], "sprite": "notes", "face": null, "face2": null, "line": "4", "itemName": "notes", "inside": null}, {"id": "d5_victor", "dzien": 5, "postac": "Victor Crane, 51", "glos": "Krótkie pytania, zero small talku. Zawsze: „Kto może to podpisać?” Pokwitowanie w dwóch egzemplarzach.", "typ": "kontroler jawny", "rzecz": "Szara teczka kontroli zapinana na klamrę", "wnetrze": [{"sekret_id": "d5_wykaz_dopisany", "co_widac": "W teczce wykaz wydań z poprzedniej zmiany. Pozycje „prawa rękawiczka T. Ward” i „paczka bez wpisu” dopisano innym tuszem. Obok parafa V.C.", "co_z_tego_wynika": "Victor dopisał obie pozycje sam, po fakcie. Wie o wydaniach poprzednika od dawna."}], "wejscie": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, zapinaną na klamrę. O siódmej muszę rozliczyć cały tydzień z księgą wydań. Czy ktoś ją oddał?", "wejscie_jesli": {"d4_iris:wydaj_cicho": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, zapinaną na klamrę. O siódmej muszę rozliczyć tydzień z księgą wydań, a w tym tygodniu brakuje mi jednej paczki. Czy ktoś ją oddał?", "d4_iris:zatrzymaj": "Victor Crane, inspekcja przewozów. Zgubiłem teczkę kontroli, szarą, zapinaną na klamrę. O siódmej rozliczam tydzień z księgą wydań. W depozycie leży paczka, którą chcę zobaczyć. Czy ktoś oddał teczkę?"}, "tury": [{"pytania": [{"tekst": "Jak wygląda teczka?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary skaj, klamra z przodu, naklejka inspekcji na rogu. W środku formularze, pieczątka i bilety kontrolne.", "mina": "mowi"}, {"tekst": "Gdzie została?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, 4:10. Położyłem ją na siedzeniu obok. Wysiadłem przy zajezdni bez niej. To się nie zdarza.", "mina": "neutralna"}, {"tekst": "Dlaczego inspektor sam jeździ nocnym tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kontrola ma sprawdzać, jak jest, a nie jak ma być. A w nocy jest zawsze trochę inaczej niż w grafikach.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co kontrolujecie w tym biurze?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zgodność księgi wydań ze stanem magazynu i z kwitami. Po pierwsze wpis, po drugie kwit, po trzecie podpis. Czasem brakuje któregoś.", "mina": "mowi"}, {"tekst": "Czym potwierdzi, że teczka jest jego?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Inicjały V.C. na wewnętrznej klapie. I pieczątka z numerem inspekcji: czterdzieści siedem.", "mina": "neutralna"}, {"tekst": "Czy ostatnie wydania w tym biurze były poprawne?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wszystkie. Jedna paczka bez wpisu i jedna rękawiczka bez księgi. Dlatego teczka jest mi potrzebna.", "mina": "neutralna"}, {"tekst": "W teczce jest wykaz z dopisanymi pozycjami i parafą V.C. Kto je dopisał?", "ton": "niewygodne", "wymaga": "d5_wykaz_dopisany", "odpowiedz": "Ja. Dopisałem tydzień po odejściu poprzednika, z jego własnych słów. Nie mam na to dowodu, tylko jego słowo. To nie jest zgodne z regulaminem, więc proszę tego nie powtarzać.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co się stanie, jeśli teczki nie będzie rano?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Audyt przesunie się o tydzień. W tym czasie ktoś zdąży poprawić księgę. Chciałbym uniknąć poprawiania.", "mina": "mowi"}, {"tekst": "Odbierze pokwitowanie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Victor Crane. Pokwitowanie w dwóch egzemplarzach, jeden zostaje w księdze. Zawsze.", "mina": "neutralna"}, {"tekst": "Czy ktoś spoza inspekcji powinien widzieć zawartość teczki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. Zajrzenie przez osobę nieuprawnioną to naruszenie. Pytam wprost: czy ktoś zajrzał? Jeśli tak, chcę znać nazwisko.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Dwa egzemplarze pokwitowania. Wpis: teczka zwrócona nienaruszona.", "zysk": "Audyt idzie zgodnie z planem, a Victor zapamięta, że biuro oddaje to, co należy.", "strata": "Podpisujesz zdanie „zwrócona nienaruszona”, nawet jeśli teczka była otwarta.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Teczka odebrana. Przejrzałem tydzień: dwie pozycje bez wpisu. Na razie notuję. Do piątku proszę o uzupełnienie dokumentów. — V. Crane"}}, {"akcja": "odmow", "kasa": -60, "reakcja": "Rozumiem. Zapiszę odmowę wydania dokumentu kontroli i wrócę z pismem.", "zysk": "Nikt nie może zarzucić Ci wydania bez procedury.", "strata": "Inspektor zapisuje odmowę i potrąca z wypłaty 60 dolarów za utrudnianie kontroli.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Pismo z inspekcji: odmowa wydania dokumentu kontroli osobie uprawnionej. Potrącono 60 dolarów z wypłaty. Kontrola zostanie przedłużona o tydzień. — V. Crane"}}], "sprite": "teczka", "face": "inspektor", "face2": null, "line": "6", "itemName": "teczka kontroli", "inside": {"img": "W17", "x": 0.66, "y": 0.32}}, {"id": "d6_ada", "dzien": 6, "postac": "Ada Vale, 10", "glos": "Dosłowna, opisuje drobiazgi, których dorośli nie zauważają. Gdy się boi, mówi szeptem.", "typ": "uczciwa", "rzecz": "Szary pluszowy królik z jednym uchem doszytym czerwoną nitką", "wnetrze": [], "wejscie": "Dobry wieczór. Jestem Ada, mam dziesięć lat. Zgubiłam królika, ma na imię Pan Kłapek. Lewe ucho jest doszyte czerwoną nitką, zostawiłam go na ławce przy pętli szóstki. Mama mówiła, że tu oddają rzeczy, jeśli są dobrze opisane.", "wejscie_jesli": {"d1_rosa:wydaj": "Dobry wieczór. Jestem Ada, córka Rosy z pralni. Mama mówi, że dostała całą wypłatę, bo ktoś ją oddał. Dlatego przyszłam. Zgubiłam królika, Pan Kłapek, lewe ucho doszyte czerwoną nitką, ławka przy pętli szóstki.", "d1_rosa:odmow": "Dobry wieczór. Jestem Ada, córka Rosy z pralni. Mama mówi, że dostała mniej wypłaty przez to okienko, ale że to nie wasza wina. Zgubiłam królika, Pan Kłapek, lewe ucho doszyte czerwoną nitką, ławka przy pętli szóstki."}, "tury": [{"pytania": [{"tekst": "Jak wygląda Pan Kłapek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary, jedno ucho dłuższe. Lewe doszyte czerwoną nitką, bo oryginalne urwało się w zeszłym roku. Pachnie kuchnią.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie go zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Na pętli linii szóstej. Pobiegłam za kotem, a on został na ławce. Kot nie wrócił, królik też nie.", "mina": "neutralna"}, {"tekst": "Dlaczego dziecko jeździ tramwajem w nocy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo mama pracuje w nocy w pralni na Dokach. Jeżdżę z nią, a po drodze zbieram rzeczy, które ludzie gubią. Oddaję je do biura.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co oddałaś już do tego biura?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dwie rękawiczki, książkę, parasol i jeden klucz. Za każdym razem ktoś pisze na kwicie, że dobrze zrobiłam. Chcę kwit, że dobrze zrobiłam.", "mina": "mowi"}, {"tekst": "Co jeszcze widziałaś przy pętli?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Panią w jasnych rękawiczkach. Postawiła puszkę po herbacie na ławce i poszła do tramwaju. Puszkę dałam konduktorowi, a on dołożył ją do skrzynek.", "mina": "neutralna"}, {"tekst": "Czy mama wie, że zbierasz cudze rzeczy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wie. Ale mówi, żebym nie oddawała tych, które wyglądają jak czyjeś sekrety. Nie wiem, które.", "mina": "neutralna"}, {"tekst": "W puszce jest odcinek z numerem. Skąd ta puszka?", "ton": "niewygodne", "wymaga": "d6_puszka_odcinek", "odpowiedz": "Od pani w jasnych rękawiczkach. Widziałam ją u niej przy kasetce, w kamienicy. Ma na imię Iris. Proszę nie mówić, że to ja powiedziałam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Kto cię odbierze, jak królik się znajdzie?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Mama. O szóstej, przy pralni na Dokach. Jeśli ktoś tam będzie czekał, to jest dobrze.", "mina": "mowi"}, {"tekst": "Wpisać cię jako znalazczynię puszki?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Tak, ale bez adresu. Mama mówi, że adresy są dla poczty, a nie dla biura.", "mina": "neutralna"}, {"tekst": "Co zrobisz, jeśli królik się nie znajdzie?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zrobię nowego z papieru. Tylko będzie bez ucha, bo nie umiem szyć.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "etykieta": "Wydaj królika i wpisz ją jako znalazczynię (bez adresu)", "reakcja": "To jest dowód? Mogę go pokazać mamie? Tu jest napisane, że dobrze zrobiłam.", "zysk": "Ada odzyskuje królika i dostaje kwit, a puszka ma w księdze znalazczynię i pochodzenie.", "strata": "W księdze zostaje ślad, skąd pochodzi puszka z numerem. Jeśli Iris zajrzy, wie, że ktoś ją widział.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Kłapek wrócił. Mama powiedziała, że ten kwit jest ładny, i schowała go do szuflady z dokumentami. A pani w jasnych rękawiczkach zapytała mnie wczoraj, czy coś ostatnio znalazłam. Powiedziałam, że nic. — Ada"}}, {"akcja": "wydaj_bez_wpisu", "etykieta": "Wydaj królika, puszkę zostaw bez wpisu", "reakcja": "Dziękuję. A kwit? Tylko królik? No dobrze.", "zysk": "Ada odzyskuje królika i jest bezpieczna: nic w księdze jej nie wskazuje.", "strata": "Nie ma kwitu ani wpisu, a Ada czuje, że zrobiła coś źle. Puszka zostaje bez historii.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Ada nie przyszła w środę. Rosa napisała: „Ada mówi, że nie wolno oddawać rzeczy z numerkami. Proszę jej nie dawać więcej zadań.” — R. Vale"}}], "sprite": "krolik", "face": null, "face2": null, "line": "6", "itemName": "pluszowy królik", "inside": null}, {"id": "d6_leo", "dzien": 6, "postac": "Leo Marsh, 46", "glos": "Zamiast dat podaje kursy, przystanki i godziny. Żartuje z własnego życia, ukradkiem spogląda na nadgarstek.", "typ": "uczciwy, milczy", "rzecz": "Mosiężny zegarek kieszonkowy z łańcuszkiem", "wnetrze": [{"sekret_id": "d6_zegarek_list", "co_widac": "Za tarczą zegarka złożony list przewozowy z dopiskiem długopisem: „puszka bez nadawcy”. Pismo pochyłe, podpis Marsh.", "co_z_tego_wynika": "Leo dopisał puszkę do wykazu po podpisaniu i wie, że nikt jej nie zgłosił."}], "wejscie": "Leo Marsh, konduktor czwórki i szóstki. Zgubiłem zegarek kieszonkowy, mosiężny, z ryską na szkle. Bez niego nie pilnuję kursów, a dziś kontrola zbiera mój wykaz dostaw za cały tydzień.", "tury": [{"pytania": [{"tekst": "Jak wygląda zegarek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Mosiądz, pęknięte szkiełko na czwartej, łańcuszek z jednym ogniwem inaczej. Spóźnia się dwie minuty na dobę. Znam go lepiej niż żonę.", "mina": "mowi"}, {"tekst": "Gdzie go zgubiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, kurs 23:05 z Doków. Wypadł mi z kamizelki na przystanku Rynek, o 23:31, kiedy kasowałem bilety.", "mina": "neutralna"}, {"tekst": "Dlaczego konduktor nosi własny zegarek?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo służbowy chodzi według zajezdni, a moja zmiana według mnie. Za to kontrola chodzi według księgi.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co jest wygrawerowane pod wiekiem?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "„L.M. za trzydzieści lat”. Żona kazała wygrawerować, a potem się wyprowadziła. Zegarek został.", "mina": "emocja"}, {"tekst": "Co dokładnie podpisujesz w wykazie dostaw?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Ile skrzynek z której linii. Nie zaglądam do skrzynek, bo nie moje. Podpisuję, że przyjechały.", "mina": "mowi"}, {"tekst": "Zdarza się podpisać coś, czego się nie widziało?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Zdarza się każdemu. Oficjalny wykaz jest wykazem. Co do reszty, zdarza się.", "mina": "klamie"}, {"tekst": "Za tarczą jest list przewozowy z dopiskiem „puszka bez nadawcy”. Czyje to pismo?", "ton": "niewygodne", "wymaga": "d6_zegarek_list", "odpowiedz": "Moje. Dopisałem po podpisie, bo ktoś na pętli wsunął mi puszkę do wozu i powiedział: bez nadawcy, tak jest dobrze. Kto, tego nie powiem. Jeszcze jeżdżę tą linią.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Dokąd teraz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kurs 02:10 do Doków, potem dwa przystanki, śniadanie i sen. Stary rytm, nawet bez żony.", "mina": "mowi"}, {"tekst": "Podpisze odbiór nazwiskiem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Leo Marsh, numer służbowy trzy-jeden-dwa. Podpis z zakrętem na M, tak jak na wykazie.", "mina": "neutralna"}, {"tekst": "Co zrobi, jeśli zegarek nie wróci?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Kupię nowy. Ale nie będzie się spóźniał dwie minuty, a ja do tych dwóch minut jestem przywiązany.", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dwie minuty do tyłu, jak zawsze. Dziękuję.", "zysk": "Leo wraca do pracy i będzie pamiętał, że biuro oddaje to, co należy.", "strata": "List z dopiskiem „puszka bez nadawcy” odchodzi razem z zegarkiem, a z nim jedyny dowód pochodzenia puszki.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Kontroler pytał dziś o puszkę. Powiedziałem, że oficjalny wykaz jest wykazem. Gdyby ktoś przy okienku zapytał, kto mi ją dał, nie wiem. Dziękuję za zegarek. — L. Marsh"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj zegarek jako dowód", "reakcja": "Do rana. Dobrze. Spóźnię się o dwie minuty więcej, niż zwykle.", "zysk": "List zostaje w biurze jako dowód w sprawie puszki.", "strata": "Leo traci zegarek na całą noc, a Ty zyskujesz powód, żeby cię nie lubił.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Leo Marsh: „Dostaję pisma z inspekcji, że mój wykaz jest niezgodny. To przez ten list, który zatrzymaliście. Podpiszę wszystko, co każecie, ale proszę o zegarek.”"}}], "sprite": "zegarek", "face": null, "face2": null, "line": "6", "itemName": "zegarek kieszonkowy", "inside": null}, {"id": "d7_kit", "dzien": 7, "postac": "Kit Navarro, 17", "glos": "Sarkastyczny, krótkie zdania. Wszystko mówi tak, jakby było mu wszystko jedno, ale pilnuje każdego słowa.", "typ": "uczciwy", "rzecz": "Czarne słuchawki nauszne z naklejką kota w kasku", "wnetrze": [], "wejscie": "No hej, Kit. Zgubiłem słuchawki w czwórce, czarne, nauszne, na pałąku naklejka z kotem w kasku. Pracuję w kopiarni na Rynku i bez nich nie wytrzymam do rana, bo cały czas ktoś gada przy kserze.", "tury": [{"pytania": [{"tekst": "Jak wyglądają słuchawki?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Czarne, nauszne, lewa muszla pęknięta i sklejona taśmą. Na pałąku kot w kasku. Nie śmiej się.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie zostały?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czwórka, kurs po północy. Zsunęły mi się z szyi za siedzenie. Wysiadłem przy Rynku i dopiero w kopiarni się zorientowałem.", "mina": "neutralna"}, {"tekst": "Ile masz lat, żeby pracować w nocy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Siedemnaście. Tak, wiem. Szef mówi, że jestem praktykantem. Nie mów nikomu, bo mnie wywalą.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co robisz w tej kopiarni?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Kseruję, laminuję, drukuję plakaty. Ludzie wchodzą w nocy z dziwnymi sprawami: ulotki na zaginione koty, życzenia dla teściowej. Wiem o ludziach więcej, niż chcę.", "mina": "mowi"}, {"tekst": "Pamiętasz jakieś zamówienia z ostatniego tygodnia?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "W czwartek o 22:15 facet w szarym płaszczu zamówił sto ulotek ze zdjęciem kobiety i napisem „ZAGINIONA”. Zapłacił gotówką. Powiedział, że potrzebuje na piątek rano.", "mina": "mowi", "ustawia": "d7_kit_ulotki"}, {"tekst": "Skąd wiesz, że to nie była zwykła ulotka?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wielkie litery, ZAGINIONA, i data zaginięcia: piątek. A zamawiał w czwartek. Skąd w czwartek wiadomo, że ktoś zniknie w piątek? Ja tylko liczę.", "mina": "neutralna"}]}, {"pytania": [{"tekst": "Dasz radę dotrwać do rana bez słuchawek?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dojść tak, wytrzymać nie. Człowiek, który godzinę słucha cudzych rozmów, potrzebuje własnej muzyki.", "mina": "mowi"}, {"tekst": "Podpiszesz odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Kit Navarro, sprawdź, czy z jednym r. Ale nie wpisuj, że kopiarnia, dobra? Wpisz tylko Rynek.", "mina": "neutralna"}, {"tekst": "Czy ktoś pytał cię już o te ulotki?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Jeszcze nie. A co, powinien ktoś?", "mina": "mowi"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki! I zero gadania o kopiarni, dobra? Słowo.", "zysk": "Kit wraca do pracy ze słuchawkami, a Ty wiesz, co widział.", "strata": "Informacja o ulotkach zostaje bez dowodu: Kit nie zezna ani nie pokaże rachunku.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Szef znalazł rachunek za ulotki i chciał wiedzieć, kto się wygadał. Powiedziałem, że nikt. Wpiszcie, że słuchawki były moje i tyle. Dzięki. — Kit"}}, {"akcja": "zadzwon", "etykieta": "Zadzwoń po Noaha: Kit widział zamówienie", "reakcja": "No nie! Nie dzwoń na policję! Miałem tylko odebrać słuchawki!", "zysk": "Noah dowiaduje się o ulotkach i może sprawdzić rachunek w kopiarni.", "strata": "Kit traci pracę i zaufanie do biura, bo zeznanie wyjdzie na jaw.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Dziękuję za telefon. Rachunek z kopiarni potwierdza godzinę. To nie dowód, ale kierunek. Chłopak jest niepełnoletni, więc zostanie to między nami. — N. Reyes"}}], "sprite": "sluchawki", "face": null, "face2": null, "line": "11", "itemName": "słuchawki", "inside": null}, {"id": "d7_evan", "dzien": 7, "postac": "Evan Doyle, 37", "glos": "Grzecznie, pełnymi zdaniami, pod presją wraca do tego samego pytania: „którą linią?”. Poprawia wygnieciony mankiet.", "typ": "częściowo kłamca", "rzecz": "Brązowe skórzane etui na klucze z zatrzaskiem", "wnetrze": [{"sekret_id": "d7_etui_klucze", "co_widac": "W etui dwa klucze: nowoczesny od mieszkania i stary kluczyk z zawijasem, od skrytki. W kieszonce kartonik z nadrukowanym znakiem nieskończoności.", "co_z_tego_wynika": "Stary kluczyk i kartonik należą wyłącznie do Mai, to jej prywatna skrytka. Evan zna tylko klucz od mieszkania."}], "wejscie": "Dobry wieczór. Evan Doyle. Znalazły się klucze mojej żony, skórzane etui z dwoma kluczami? Proszę o ich wydanie, to klucze do naszego mieszkania. I proszę powiedzieć, którą linią przyjechały.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_evan": "Dobry wieczór. Evan Doyle. Odebrałem tu telefon żony i przeczytałem wiadomość od Leny. Teraz proszę o klucze Mai. To nasze mieszkanie, mam do nich prawo. I proszę powiedzieć, którą linią przyjechały.", "d3_maz_i_siostra:wydaj_lena": "Dobry wieczór. Evan Doyle. Telefon żony oddano jej siostrze, więc dziś chcę tylko kluczy do naszego mieszkania. Proszę o nie, bez wymówek. I proszę powiedzieć, którą linią przyjechały.", "d3_maz_i_siostra:zatrzymaj": "Dobry wieczór. Evan Doyle. Telefon żony nadal tu leży, a ja go nie dostałem. Proszę choć o klucze do naszego mieszkania. I proszę powiedzieć, którą linią przyjechały."}, "tury": [{"pytania": [{"tekst": "Jak wygląda etui?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Skórzane, brązowe, na zatrzask. W środku dwa klucze i kartonik z jakimś znakiem, nie wiem po co. Maya nosiła je w kieszeni płaszcza.", "mina": "mowi"}, {"tekst": "Który klucz jest do czego?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Mały, nowoczesny, do mieszkania. Drugiego nie znam. Stary, z zawijasem. Pewnie do czegoś u jej mamy.", "mina": "neutralna"}, {"tekst": "Skąd wiadomo, że to klucze Mai?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo to jej płaszcz miał kieszeń na etui. Dostała je ode mnie, trzy lata temu. Czy to nie wystarcza?", "mina": "emocja"}]}, {"pytania": [{"tekst": "Od kiedy Maya zostawia rzeczy w tramwajach?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nigdy. Maya pilnuje każdej rzeczy. Dlatego zgłosiłem policji, że to nie jest jej zachowanie.", "mina": "mowi"}, {"tekst": "Którą linią przyjechała dostawa z etui?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Proszę po prostu powiedzieć, którą linią. Jedenastką? Szóstką? Tylko tyle. To nie jest tajemnica państwowa.", "mina": "emocja"}, {"tekst": "Po co Evanowi trasa dostawy?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo jeśli rzeczy Mai pojawiają się na jednej linii, wiem, w którą stronę szukać. To logiczne, prawda? Nie rozumiem, dlaczego pytasz.", "mina": "neutralna"}, {"tekst": "Ulotki z twarzą Mai zamówiono w czwartek o 22:15. Przed zgłoszeniem. Dlaczego?", "ton": "niewygodne", "wymaga": "d5_notes_ulotki|d7_kit_ulotki", "odpowiedz": "Zamówiłem je, bo Maya mówiła, że odejdzie. W czwartek wieczorem. Wiedziałem, że zrobi to naprawdę. Zgłosiłem rano, bo miałem nadzieję, że wróci przed policją. Proszę nie mówić tego Noahowi. Zabrzmi to źle.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co zrobi z kluczami?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Wejdę do mieszkania. Maya może wrócić i nie zastać zmienionych zamków. Chcę, żeby miała do czego wracać.", "mina": "mowi"}, {"tekst": "Podpisze odbiór?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Evan Doyle. Mogę pokazać dowód i akt ślubu, mam wszystko w teczce.", "mina": "neutralna"}, {"tekst": "Co, jeśli Maya nie chce wracać?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy chcę to usłyszeć od niej. Nie od siostry, nie od policji, od niej. Dwa zdania i zamknę sprawę.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj_evan", "etykieta": "Wydaj etui Evanowi", "reakcja": "Dziękuję. Obiecuję, że klucz do mieszkania zostanie w mieszkaniu.", "zysk": "Evan dostaje klucze do własnego domu.", "strata": "Stary kluczyk i kartonik, które mogą należeć tylko do Mai, wychodzą z biura razem z nim.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Evan otworzył jej skrytkę starym kluczem z etui. Była pusta. Maya wie teraz, że ktoś ją otwierał. Nie odpisuje mi od tygodnia. — Lena"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj dla Mai i zaproponuj Evanowi list", "reakcja": "List? Dobrze. Napiszę. Dwa zdania. Niech ona je przeczyta.", "zysk": "Etui czeka na Maję, a Evan dostaje jedyną drogę, żeby się z nią skontaktować.", "strata": "Evan wychodzi bez kluczy do własnego mieszkania i uważa, że biuro bierze stronę żony.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Napisałem list: dwa zdania. Zostawiłem go przy okienku, bo nie wiem, co jeszcze mogę zrobić. Jeśli ktoś kiedykolwiek odpisze, proszę dać znać. — Evan"}}, {"akcja": "odmow", "etykieta": "Odmów: etui nie jest jego i nie podajesz linii", "reakcja": "To nieuprzejme. Nie takiej odpowiedzi się spodziewałem.", "zysk": "Trasa dostawy zostaje tajemnicą, a Maya nie jest śledzona.", "strata": "Evan odchodzi wściekły i zaczyna szukać u Leny.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Evan stał pod moimi drzwiami od północy. Nie otworzyłam. Powiedział, że biuro odmówiło mu kluczy. Dzięki. — Lena"}}], "sprite": "klucze", "face": "maz", "face2": null, "line": "11", "itemName": "etui na klucze", "inside": {"img": "W5", "x": 0.43, "y": 0.31}}, {"id": "d8_lena_i_nora", "dzien": 8, "postac": "Lena Brandt, 31", "glos": "Lena: szybko, urywa, mówi za dużo. Nora: po kolei, na palcach, bez ozdobników.", "typ": "prawdomówne, ale każda ma swoją sprawę", "rzecz": "Szara torba narzędziowa z rozprutą podszewką", "ludzie": {"siostra": "Lena", "nora": "Nora"}, "wnetrze": [{"sekret_id": "d8_torba_kopia", "co_widac": "W rozprutej podszewce leży żółta kopia pokwitowania zaliczek z podpisem „I.” i kwotą 400 dolarów. Obok narzędzia: obcęgi, śrubokręt, miara.", "co_z_tego_wynika": "Kopia dowodzi, że Iris Bell przyjęła 400 dolarów od lokatorów. Maya schowała ją na wszelki wypadek."}], "wejscie": "Cześć, Lena Brandt. Po torbę narzędziową mojej siostry Mai: szara, rozpruta podszewka, w środku jej narzędzia. Chcę ją wziąć teraz, zanim ktoś inny zacznie zbierać rzeczy po Mai.", "wejscie_jesli": {"d3_maz_i_siostra:wydaj_lena": "Cześć, Lena Brandt. Mam już telefon Mai od was, ale hasła nie znam. Dziś po torbę narzędziową: szara, rozpruta podszewka. To kolejna rzecz siostry, którą ktoś zostawił w tramwaju.", "d3_maz_i_siostra:wydaj_evan": "Cześć, Lena Brandt. Evan ma telefon Mai, bo mu go oddaliście, więc torby nie dam mu odebrać. Szara, rozpruta podszewka, narzędzia mojej siostry. Proszę o nią."}, "tury": [{"pytania": [{"tekst": "Jak wygląda torba?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szara, sztywna, z dużym zamkiem. Podszewka rozpruta, bo Maya wkłada kleszcze bez futerału. W środku obcęgi, śrubokręt i miara.", "kto": "siostra", "mina": "mowi"}, {"tekst": "Skąd wiadomo, że to torba Mai?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Bo Maya jest elektryczką, a torbę dostała od taty. Na uchwycie wyrzeźbiła inicjały M.B., zanim wyszła za Evana.", "kto": "siostra", "mina": "mowi"}, {"tekst": "Dlaczego Maya zostawia swoje rzeczy w tramwajach?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie wiem. Naprawdę. Albo wiem, ale... nie wiem.", "kto": "siostra", "mina": "emocja"}]}, {"pytania": [{"tekst": "Ktoś jeszcze czeka za Leną?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Tak. Nora Vance, przedstawicielka lokatorów kamienicy przy Cooper Street dziewięć. Przepraszam, że wtrącam. W podszewce tej torby powinna być kopia pokwitowania, które mnie dotyczy.", "kto": "nora", "mina": "mowi"}, {"tekst": "Skąd Nora wie, co jest w cudzej torbie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Po kolei. Maya pracowała w naszej kamienicy jako elektryczka. Dostała od Iris Bell pokwitowanie zaliczek, kwoty, których Iris nie wpisała w zestawieniu. Zrobiła kopię na wszelki wypadek i pokazała mi ją.", "kto": "nora", "mina": "mowi"}, {"tekst": "Lena, wiedziałaś o kopii?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie. To znaczy wiedziałam, że Maya coś chowa, ale nie co. Nora, nie mów więcej, to sprawa mojej siostry.", "kto": "siostra", "mina": "klamie"}, {"tekst": "W podszewce jest żółta kopia pokwitowania z podpisem „I.” Czyja to sprawa?", "ton": "niewygodne", "wymaga": "d8_torba_kopia", "odpowiedz": "Iris Bell. To pokwitowanie to 400 dolarów zaliczek rodziny Okoye. Jeśli kopia przepadnie, ta rodzina zapłaci zaliczkę drugi raz.", "kto": "nora", "mina": "emocja"}]}, {"pytania": [{"tekst": "Co chcecie zrobić z torbą?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Oddać Mai. Torba jest jej, tylko jej. Jak ona się odezwie, to zaniosę.", "kto": "siostra", "mina": "mowi"}, {"tekst": "Czy zgadzacie się podzielić zawartość?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Torba dla Mai, kopia dla mnie. Albo kopia zostaje w biurze, w depozycie, z odpisem dla obu stron. Podpiszę pokwitowanie.", "kto": "nora", "mina": "neutralna"}, {"tekst": "Dlaczego Maya zostawiła kopię w torbie, którą porzuciła?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo chciała, żeby ktoś ją znalazł. Albo żeby nikt jej nie znalazł. Nie wiem. Mam dwie wersje i obie mnie przerażają.", "kto": "siostra", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj_lena", "etykieta": "Wydaj Lenie całą torbę (z kopią)", "kto": "siostra", "reakcja": "Dziękuję. Zaniosę Mai. Nora, przepraszam.", "zysk": "Lena dostaje rzecz siostry, a Maya odzyska swoje narzędzia.", "strata": "Kopia pokwitowania wychodzi razem z torbą, a Nora traci jedyny dowód przeciw Iris.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Torba poszła do Leny, razem z kopią. Iris rozmawia z nami jak zawsze, uprzejmie. Zaliczkę rodziny Okoye trzeba będzie zapłacić drugi raz. — Nora Vance"}}, {"akcja": "kopia_osobno", "etykieta": "Zarejestruj kopię osobno, torbę wydaj Lenie", "kto": "nora", "reakcja": "Podpisuję odpis. Dziękuję. Lena, pokwituj.", "zysk": "Torba wraca do Mai przez Lenę, a kopia leży w biurze z podpisami obu stron.", "strata": "Wpis w księdze nazywa kopię pokwitowania Iris Bell. Jeśli Iris zajrzy do księgi, wie, kto ją ma.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Iris Bell prosi o wgląd w rejestr depozytów za ostatni tydzień. Powołuje się na przepisy o administrowaniu budynkiem. Termin: poniedziałek. — I. Bell"}}, {"akcja": "odmow", "etykieta": "Odmów obu stronom i zatrzymaj torbę", "kto": "siostra", "reakcja": "Naprawdę? No dobrze. Maya się wścieknie.", "zysk": "Torba i kopia zostają w biurze, dopóki Maya sama po nie przyjdzie.", "strata": "Lena i Nora wychodzą z niczym, a Nora traci termin rozliczenia zaliczek.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Do soboty mam rozliczyć zaliczki. Bez kopii nie mam czego pokazać lokatorom. — Nora Vance"}}], "sprite": "torba_narzedzia", "face": "siostra", "face2": {"siostra": "siostra", "nora": null}, "line": "4", "itemName": "torba narzędziowa", "inside": {"img": "W6", "x": 0.37, "y": 0.6}}, {"id": "d8_bree", "dzien": 8, "postac": "Bree Halm, 29", "glos": "Pewna siebie, szybka, mówi do sprawy: „Słuchaj, mam paragon.” Nie zwalnia, gdy kłamie.", "typ": "profesjonalista", "rzecz": "Srebrny analogowy aparat fotograficzny z wgnieceniem w lewym rogu", "wnetrze": [{"sekret_id": "d8_aparat_naklejka", "co_widac": "Pod osłoną baterii wydrapane „R.O.” i naklejka: „Raf Okoye, Cooper Street 9, m. 4”.", "co_z_tego_wynika": "Aparat należy do Rafa Okoye, lokatora kamienicy. Bree nie jest jego siostrą ani bratem."}], "wejscie": "Cześć, Bree. Zgubiłam aparat brata, srebrny, analogowy, w jedenastce. Mam paragon i zdjęcie aparatu, bo Teo leży w szpitalu i kazał mi go odebrać. To jedyna rzecz, jaka mu została po ojcu.", "tury": [{"pytania": [{"tekst": "Jak wygląda aparat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Srebrny, analogowy, skórzany pasek, wgniecenie w lewym rogu. Ma dwadzieścia lat, a wygląda jak nowy.", "mina": "mowi"}, {"tekst": "Gdzie został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jedenastka, wczoraj wieczorem. Teo zostawił go na siedzeniu, jak wsiadał do karetki.", "mina": "neutralna"}, {"tekst": "Dlaczego brat sam nie przyszedł?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Leży w szpitalu na Wharf. Noga. Kazał mi przynieść paragon i zdjęcie, bo wie, że biuro tego chce.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Jak ma na imię brat?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Teo. Teo Halm. Tak jak ja, tylko bez B.", "mina": "mowi"}, {"tekst": "Co jest na paragonie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Lombard na Rynku, siedemdziesiąt dolarów, model S-2, rok dziewięćdziesiąty ósmy. Lepszego dowodu nie ma.", "mina": "mowi"}, {"tekst": "Czy właściciel wydrapał na aparacie jakieś inicjały?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Inicjały? Teo nic nie wydrapywał. Aparat jest czysty.", "mina": "klamie"}, {"tekst": "Pod osłoną baterii wydrapane „R.O.” i adres. Czyj to aparat?", "ton": "niewygodne", "wymaga": "d8_aparat_naklejka", "odpowiedz": "R.O.? Aparat mógł mieć wcześniej innego właściciela. Teo kupił go w lombardzie, mam paragon. Nie wiem, kto go rysował.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Podpiszesz odbiór?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Bree Halm. Tak jak brat. Piszę czytelnie, mam to po mamie.", "mina": "neutralna"}, {"tekst": "Co zrobisz z aparatem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Zawiozę bratu do szpitala. Chce zrobić zdjęcie nogi. Dla pamiątki.", "mina": "mowi"}, {"tekst": "Co, jeśli właściciel zjawi się później?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Nie zjawi się. Wiem, co mówię. Znaczy znam brata.", "mina": "klamie"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dzięki, dobry z ciebie człowiek. Teo będzie wdzięczny.", "zysk": "Bree odchodzi z aparatem i paragonem, a kolejka robi się krótsza.", "strata": "Aparat Rafa Okoye trafia do kogoś innego. Jeśli Raf przyjdzie, nie ma czego wydać.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Raf Okoye, lokator z Cooper Street: „Zgubiłem aparat w jedenastce. Pod osłoną baterii mam wydrapane R.O. Czy ktoś go już odebrał? Na klatce pytała o mnie kobieta w dresie.”"}}, {"akcja": "odmow", "reakcja": "Przecież mam paragon! No dobra, wrócę z innym.", "zysk": "Aparat zostaje w biurze dla Rafa Okoye.", "strata": "Bree zapamiętuje twarz za szybą i wróci z inną historią.", "echo": {"za_dni": 3, "forma": "gosc", "tekst": "Raf Okoye odebrał aparat. Przy okienku powiedział, że kobieta w dresie pytała o niego na klatce schodowej. Powiedziała, że ma brata Teo w szpitalu. Raf nie zna żadnego Teo."}}], "sprite": "aparat", "face": null, "face2": null, "line": "4", "itemName": "aparat", "inside": null}, {"id": "d9_iris", "dzien": 9, "postac": "Iris Bell, 56", "glos": "Cicho, uprzejmie, ze zdrobnieniami. „Nie lubię naciskać” przed każdym naciskiem.", "typ": "presja", "rzecz": "Metalowy matowy piórnik na zatrzask z dwoma przedziałami", "wnetrze": [{"sekret_id": "d9_zetony_numery", "co_widac": "W dolnym przedziale pięć mosiężnych żetonów z numerami. Trzy mają te same numery co blankiet z kasetki z dnia czwartego, czwarty jest bez numeru i ma wżer po kwasie.", "co_z_tego_wynika": "Żetony to numery odbioru paczek Skrytki, nie skrzynek pocztowych."}], "wejscie": "Dobry wieczór. Iris Bell. Piórnik, w którym trzymam żetony do skrzynek pocztowych w kamienicy. Zgubiłam go w szóstce, ostatni kurs. To znów drobiazg, ale lokatorzy bez żetonów nie odbiorą poczty.", "wejscie_jesli": {"d4_iris:wydaj": "Dobry wieczór. Iris Bell, znowu. Piórnik z żetonami do skrzynek pocztowych w kamienicy, szóstka, ostatni kurs. Zeszłym razem wpis w księdze mnie zaskoczył, ale rozumiem. Ten piórnik też proszę wpisać.", "d4_iris:wydaj_cicho": "Dobry wieczór. Iris Bell. Jak miło znowu przy tej szybie. Piórnik z żetonami do skrzynek, szóstka, ostatni kurs. Mam nadzieję, że tym razem nie trzeba będzie pisać zbyt wiele.", "d4_iris:zatrzymaj": "Dobry wieczór. Iris Bell. Paczka z zeszłego tygodnia nadal leży u was. Dziś piórnik z żetonami do skrzynek, szóstka, ostatni kurs. Zakładam, że ten pójdzie szybciej."}, "tury": [{"pytania": [{"tekst": "Jak wygląda piórnik?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Metalowy, matowy, z zatrzaskiem. Dwa przedziały, w dolnym żetony. Trzymam w nim zapasowe żetony do skrzynek w kamienicy.", "mina": "mowi"}, {"tekst": "Gdzie dokładnie zginął?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, ostatni kurs, na pętli. Zostawiłam go obok torby, kiedy sięgałam po parasolkę.", "mina": "neutralna"}, {"tekst": "Dlaczego administratorka kamienicy wozi żetony tramwajem?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo kamienica ma dwa wejścia. Jedno od Cooper Street, drugie od strony pętli. Jeżdżę między nimi, drobne obowiązki.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Ile żetonów jest w piórniku?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Pięć. Wszystkie od skrzynek, wszystkie z numerami od dwunastu do piętnastu.", "mina": "klamie"}, {"tekst": "Do czego służą numery na żetonach?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Do skrzynek, rzecz jasna. Każda rodzina ma swoją.", "mina": "neutralna"}, {"tekst": "Czy żetony mają coś wspólnego z paczką z ostatnich dni?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Z paczką? Ależ skąd. Co za pomysł.", "mina": "klamie"}, {"tekst": "Trzy żetony mają numery z blankietu na kasetce, czwarty ma wżer po kwasie. Do czego służą?", "ton": "niewygodne", "wymaga": "d9_zetony_numery", "odpowiedz": "Numery odbioru paczek. Nie lubię, gdy ktoś ma rację w sprawach, które mnie dotyczą. Są paczki, które ktoś u mnie zostawia, bo chce zostawić też miasto. Nie wnikam.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Czy ktoś z kontroli pytał już o te numery?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Pan Crane? Rozmawiałam z nim wczoraj. Pytania miał krótkie jak zapałki. Nie lubię zapałek.", "mina": "mowi"}, {"tekst": "Podpisze odbiór piórnika?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Iris Bell. Wpis niech będzie, jak uznacie. Ja nie narzucam.", "mina": "neutralna"}, {"tekst": "Co, jeśli piórnik trafi do inspektora?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy będzie miał pięć żetonów i pytania, na które nie dostanie odpowiedzi ode mnie. Ale może dostać od innych, a to już wasza sprawa.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "etykieta": "Wydaj piórnik Iris i wpisz do księgi", "reakcja": "Dziękuję. Wpis oficjalny. Zapamiętam.", "zysk": "Księga jest czysta, a lokatorzy odzyskają żetony.", "strata": "Żetony z numerami paczek wychodzą z biura i znika ślad, który zainteresowałby inspektora.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Zaliczki rodziny Okoye nadal są u Iris. Dzięki, że piórnik wrócił, jej wystarczył, nam nie. — Nora"}}, {"akcja": "zatrzymaj", "etykieta": "Zatrzymaj piórnik dla inspektora (za pokwitowaniem)", "reakcja": "Rozumiem. Pan Crane będzie zadowolony. Ja także, w swoim czasie.", "zysk": "Victor dostanie żetony z numerami, których szuka.", "strata": "Iris dowiaduje się, że biuro nie jest już jej człowiekiem, a ludzie z żetonami zostają bez paczek.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Odebrałem piórnik z żetonami za pokwitowaniem. Trzy numery zgadzają się z blankietem z kasetki. Dalej zajmuję się tym sam. — V. Crane"}}], "sprite": "piornik", "face": "dama", "face2": null, "line": "6", "itemName": "piórnik", "inside": {"img": "W7", "x": 0.2, "y": 0.58}}, {"id": "d9_stahl", "dzien": 9, "postac": "Marek Stahl, 50", "glos": "Gładki, trochę za dobrze przygotowany. Odpowiada szybko i wygląda, jakby czytał z kartki.", "typ": "kontroler pod przykrywką", "rzecz": "Szary filcowy kapelusz z granatową wstążką", "wnetrze": [{"sekret_id": "d9_kapelusz_naklejka", "co_widac": "Pod wstążką naklejka: „Alder & Son, rozmiar 56”. Na podszewce wyhaftowane inicjały J.A.", "co_z_tego_wynika": "Kapelusz należy do kogoś o inicjałach J.A. i rozmiarze 56. Stahl podaje rozmiar 58 i inicjały M.S."}], "wejscie": "Dobry wieczór. Marek Stahl. Zgubiłem kapelusz w czwórce: szary, filcowy, z granatową wstążką. Jutro rano ślub koleżanki i bez kapelusza wstydzę się wejść do kościoła.", "tury": [{"pytania": [{"tekst": "Jak wygląda kapelusz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Szary filc, granatowa wstążka, rondo szerokie na trzy palce. Standardowy kapelusz.", "mina": "mowi"}, {"tekst": "Gdzie i kiedy go zostawiłeś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Czwórka, kurs o pierwszej. Położyłem go na półce nad siedzeniem. Zwykle tak robię.", "mina": "neutralna"}, {"tekst": "Co jeszcze trzeba, żeby odebrać?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Opis, paragon, świadka, cokolwiek wymagacie. Jestem do dyspozycji, procedura jest po to, żeby jej przestrzegać.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Jaki rozmiar nosi?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Pięćdziesiąt osiem. Duża głowa, ale mała inicjatywa.", "mina": "klamie"}, {"tekst": "Co jest wewnątrz kapelusza?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Podszewka i moje inicjały, M.S. Haftowane, ślubny prezent.", "mina": "klamie"}, {"tekst": "Czy to pierwsza wizyta w tym biurze?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Pierwsza. Jestem z drugiej strony miasta, rzadko tu bywam.", "mina": "neutralna"}, {"tekst": "Pod wstążką jest naklejka z rozmiarem 56 i inicjały J.A. Czyj to kapelusz?", "ton": "niewygodne", "wymaga": "d9_kapelusz_naklejka", "odpowiedz": "...Mój. Inicjały? J.A. to... Józef Alder, mój wujek. Rozmiar 56, no tak, pomyliłem się. Nie róbmy z tego sprawy, jest rano ślub.", "mina": "klamie"}]}, {"pytania": [{"tekst": "Podpisze odbiór?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Marek Stahl. Ale proszę nie robić z tego sprawy, mam spotkanie.", "mina": "mowi"}, {"tekst": "Do kogo można zadzwonić, żeby potwierdzić?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Do nikogo. Mieszkam sam. Chyba że to test, ha, ha.", "mina": "klamie"}, {"tekst": "Czy ktoś przysłał go do tego biura?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Skąd. Zgubiłem kapelusz, tyle.", "mina": "klamie"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję. Wszystko poszło bardzo sprawnie.", "zysk": "Mężczyzna wychodzi z kapeluszem, a kolejka jest krótka.", "strata": "To był test inspekcji: wydanie bez weryfikacji zapisuje się jako uchybienie, a kapelusz J.A. nie wróci do właściciela.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Test wydania: M. Stahl, kapelusz. Wydano bez weryfikacji inicjałów i rozmiaru. Uchybienie. Potrącenie 40 dolarów z wypłaty. — V. Crane"}}, {"akcja": "odmow", "reakcja": "Doskonale. Zapiszę w protokole, że procedura została zachowana.", "zysk": "Test inspekcji zaliczony: Victor zapamięta, że biuro nie rozdaje rzeczy bez dowodu.", "strata": "Kapelusz J.A. czeka na właściciela, który może się nie zgłosić.", "echo": {"za_dni": 1, "forma": "list", "tekst": "Test wydania zaliczony. Stanowisko pracuje zgodnie z regulaminem, a nie zgodnie z tym, co mówił poprzednik. Odnotowuję. — V. Crane"}}], "sprite": "kapelusz", "face": null, "face2": null, "line": "11", "itemName": "kapelusz", "inside": null}, {"id": "d10_vera", "dzien": 10, "postac": "Vera Kovacs, 62", "glos": "Najpierw miejsce, potem rzecz, na końcu nazwisko. Dzwoni kluczami przy pasie, kiedy się wstydzi.", "typ": "uczciwa, ukrywa", "rzecz": "Blaszane pudełko zapinane na sprzączkę", "wnetrze": [{"sekret_id": "d10_pudelko_karta", "co_widac": "W pudełku pasek od zegarka bez tarczy i karta inwentarza szuflady z numerem 6. Ten sam numer jest na szufladzie w biurze, w której leży klucz bez zamka.", "co_z_tego_wynika": "Szuflada w biurze należała do Sama. Klucz bez zamka otwiera tę szufladę."}], "wejscie": "Dobry wieczór. Vera Kovacs, zaplecze tramwajowe, hala trzecia. Zlikwidowaliśmy szafkę Sama Holta i wyjęłam z niej blaszane pudełko, ale zgubiłam je w jedenastce. Muszę je oddać, zanim ktoś zapyta, gdzie jest.", "tury": [{"pytania": [{"tekst": "Jak wygląda pudełko?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Blaszane, duże jak bochenek, na sprzączkę. W środku pasek od zegarka, pod nim kartka z numerem szuflady.", "mina": "mowi"}, {"tekst": "Jak je zgubiłaś?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Hala trzecia, wózek, jedenastka do Doków. Niosłam trzy rzeczy w dwóch rękach, jedną wsunęłam pod siedzenie.", "mina": "neutralna"}, {"tekst": "Kim jest Sam Holt?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Poprzednik z tego okienka. Odszedł pięć tygodni temu. Szafkę miał u nas w hali, bo nocna zmiana trzyma tam rzeczy.", "mina": "mowi"}]}, {"pytania": [{"tekst": "Co się dzieje z Samem teraz?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Nie wiem. Wezwałam go pismem po resztę rzeczy. Odbiera osobiście, za dwa tygodnie, tak mu napisałam.", "mina": "mowi"}, {"tekst": "Co jeszcze było w szafce?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Teczka osobowa. Pusta. Trzymałam ją tam, żeby szafka wyglądała na zajętą. To nic złego.", "mina": "mowi"}, {"tekst": "Dlaczego nie oddałaś pudełka od razu do biura?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo najpierw Sam, potem inwentarz, potem pudełko. Taki porządek.", "mina": "neutralna"}, {"tekst": "Numer szuflady z karty pasuje do szuflady z kluczem bez zamka. Kto go trzymał?", "ton": "niewygodne", "wymaga": "d10_pudelko_karta", "odpowiedz": "Ja. Sam zostawił mi go tydzień przed odejściem: „gdyby ktoś zapytał, powiedz, że nic nie ma”. Włożyłam klucz do szuflady, jak kazał. Przepraszam, że nie mówiłam wcześniej.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Podpisze odbiór?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Vera Kovacs, numer kadrowy dziewięć-osiem-cztery. Proszę zapisać: miejsce, rzecz, nazwisko.", "mina": "mowi"}, {"tekst": "Czy Sam wie, że pudełko się znalazło?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Jeszcze nie. Jak się dowie, że leżało tutaj, może przyjść wcześniej.", "mina": "neutralna"}, {"tekst": "Czy ktoś pytał o rzeczy Sama?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Inspektor, Crane. Dwa razy. Odpowiedziałam, że wszystko jest w inwentarzu. Nie powiedziałam, że inwentarz jest niepełny.", "mina": "emocja"}]}], "decyzje": [{"akcja": "zatrzymaj", "etykieta": "Zatrzymaj pudełko jako rzecz Sama (do jego odbioru)", "reakcja": "Dobrze. Zostanie u was. Niech Sam sam zadecyduje.", "zysk": "Pudełko i karta inwentarza zostają w biurze, a Sam odbierze je osobiście.", "strata": "Vera nie zamknie inwentarza, a ktoś z zaplecza będzie pytał, gdzie jest pudełko.", "echo": {"za_dni": 2, "forma": "list", "tekst": "Pudełko u was. Inspektor pytał o nie wczoraj. Powiedziałam, że leży w biurze rzeczy znalezionych w depozycie. Mam nadzieję, że to prawda. — V. Kovacs"}}, {"akcja": "wydaj", "etykieta": "Wydaj pudełko Verze (do archiwum zaplecza)", "reakcja": "Dziękuję. Archiwum zaplecza, tak jak trzeba.", "zysk": "Inwentarz zaplecza jest kompletny, a Vera ma spokój.", "strata": "Karta z numerem szuflady wychodzi z biura i nikt już nie zestawi szuflady z Samem.", "echo": {"za_dni": 3, "forma": "list", "tekst": "Zamknęłam inwentarz. Pudełko leży w archiwum zaplecza. Sam dostał pismo o odbiorze reszty rzeczy. — V. Kovacs"}}], "sprite": "pudelko_blaszane", "face": null, "face2": null, "line": "11", "itemName": "pudełko", "inside": {"img": "W8", "x": 0.45, "y": 0.65}}, {"id": "d10_dario", "dzien": 10, "postac": "Dario Esposito, 48", "glos": "Mówi o jedzeniu, żartuje, wszystko mierzy łyżeczkami. Oferuje kanapkę zamiast pieniędzy.", "typ": "uczciwy", "rzecz": "Gruby zeszyt z przepisami w tłustej okładce, z gumką", "wnetrze": [{"sekret_id": "d10_zeszyt_sam", "co_widac": "Na ostatniej stronie rachunki klientów baru. Pozycja: „S., nocny z biura rzeczy, zupa, 13 $, niezapłacone. Ostatni raz pięć tygodni temu.”", "co_z_tego_wynika": "Sam jadał w barze codziennie, a od pięciu tygodni się nie pokazał i został dłużny 13 dolarów."}], "wejscie": "Dobry wieczór, Dario, kucharz z całonocnego baru przy Rynku. Zgubiłem zeszyt z przepisami, gruby, w tłustej okładce, w szóstce. To wszystko, co umiem, a w piątek jest konkurs na zupę dnia.", "tury": [{"pytania": [{"tekst": "Jak wygląda zeszyt?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Gruby, tłusta okładka, gumka nasiąknięta rosołem. Wygląda jak kawał mięsa, który ktoś przez pomyłkę zamknął w kartonie.", "mina": "mowi"}, {"tekst": "Gdzie został?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Szóstka, ostatni kurs. Kładłem go na kolanach, ale zsunął mi się, kiedy zasnąłem. Kucharz po dwunastu godzinach śpi na stojąco.", "mina": "neutralna"}, {"tekst": "Dlaczego jeden zeszyt to wszystko?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Bo wszystko, co umiem, jest w nim. Babcia zapisała, ja uzupełniłem. Bez niego jestem człowiekiem z nożem.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Który przepis jest najważniejszy?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Zupa ogórkowa babci. Pół łyżeczki cukru i trzy liście laurowe. Nikt nie wie, że laur wkłada się na początku, nie na końcu.", "mina": "mowi"}, {"tekst": "Co jeszcze jest w zeszycie?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Rachunki klientów i zamówienia. Notuję, kto co lubi i kto ile jest dłużny.", "mina": "mowi"}, {"tekst": "Czy ktoś ma w zeszycie niezapłacony rachunek?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Kilku. Nie ma o czym mówić, to są drobne.", "mina": "neutralna"}, {"tekst": "W zeszycie jest rachunek: nocny z biura, zupa, 13 dolarów, niezapłacone. Kto to?", "ton": "niewygodne", "wymaga": "d10_zeszyt_sam", "odpowiedz": "Sam. Poprzedni z tego okienka. Przychodził o piątej trzydzieści, zupa i milczenie. Od pięciu tygodni ani razu. Nie chcę tych trzynastu dolarów, chcę wiedzieć, czy żyje.", "mina": "emocja"}]}, {"pytania": [{"tekst": "Podpisze odbiór?", "ton": "uprzejme", "wymaga": null, "odpowiedz": "Dario Esposito, dwa s, nie jak lekarz.", "mina": "mowi"}, {"tekst": "Co zrobi z zeszytem?", "ton": "rzeczowe", "wymaga": null, "odpowiedz": "Przepiszę wszystko na czysto, w trzech egzemplarzach. Jeden zostawię u was, żeby się nie zgubił.", "mina": "mowi"}, {"tekst": "A jeśli zeszyt nie wróci?", "ton": "niewygodne", "wymaga": null, "odpowiedz": "Wtedy zupę dnia ugotuję z wody i uporu. Ale nie w piątek.", "mina": "emocja"}]}], "decyzje": [{"akcja": "wydaj", "reakcja": "Dziękuję! Kanapkę? Z serem, jeszcze ciepła.", "zysk": "Zeszyt wraca do Daria, a w piątek będzie zupa na konkurs.", "strata": "Dario odchodzi bez odpowiedzi, co z Samem, jeśli nie padło pytanie o rachunek.", "echo": {"za_dni": 3, "forma": "list", "tekst": "W piątek zupa ogórkowa wygrała konkurs. Zostawiłem dla biura porcję w termosie pod drzwiami. Jeśli Sam kiedykolwiek wróci, powiedzcie mu, że zupa czeka, a dług umorzony. — Dario"}}, {"akcja": "odmow", "reakcja": "Rozumiem, procedura. Zrobię zupę dla całego biura jako dowód.", "zysk": "Zeszyt zostaje w biurze, dopóki Dario nie przyniesie dokumentu.", "strata": "Dario traci noc przygotowań do konkursu.", "echo": {"za_dni": 2, "forma": "gosc", "tekst": "Dario wrócił z legitymacją z baru i termosem zupy ogórkowej. Zeszyt odebrany. Zupa była dobra, a konkurs wygrała jak gdyby nigdy nic."}}], "sprite": "ksiazka", "face": null, "face2": null, "line": "4", "itemName": "zeszyt z przepisami", "inside": null}];window.EXTRA={"2": {"sprite": "szalik", "itemName": "szalik", "line": "4", "inside": null, "wnetrze": [{"sekret_id": "d2_szalik_md", "co_widac": "Pod zagiętą metką wyhaftowane inicjały M.D. W wewnętrznej kieszonce złożony bilet miesięczny na linię 4, imienny: Maya Doyle.", "co_z_tego_wynika": "Szalik należy do Mai Doyle, którą mąż zgłosił jako zaginioną. Maya zostawiła go w tramwaju."}]}, "6": {"sprite": "puszka", "itemName": "puszka po herbacie", "line": "6", "inside": {"img": "W4", "x": 0.23, "y": 0.44}, "wnetrze": [{"sekret_id": "d6_puszka_odcinek", "co_widac": "Pod ruchomym dnem puszki leży odcinek odbioru. Numer jest z tego samego bloczka co blankiet w płóciennej paczce Iris Bell z dnia czwartego.", "co_z_tego_wynika": "Puszka należy do obiegu paczek Skrytki."}]}};window.WIECZOR={"1": [{"kto": "Elias, numerek 1", "tekst": "Elias przyszedł pod koniec zmiany. „Czy jest już oprawka po mojej żonie?” Nie było. Podziękował i został chwilę przy szybie, jakby spodziewał się, że coś się zmieni."}], "2": [{"kto": "Elias, numerek 1", "tekst": "Elias, ten sam numerek. Zapytał o oprawkę, a potem, czy poprzedni pracownik zostawił jakąś notatkę o jej poszukiwaniach. Nie zostawił."}], "3": [{"kto": "Elias, numerek 1", "tekst": "Burza. Elias przyszedł w deszczu, z parasolem bez rączki. „Czy jest oprawka?” Nie było. Wziął od okienka suchy numerek i złożył go w prostokąt ciaśniejszy niż zwykle."}], "4": [{"kto": "Elias, numerek 1", "tekst": "Elias powiedział, że poprzedni pracownik obiecał szukać oprawki z własnej kieszeni. Zapytany, co to znaczy, odpowiedział, że nie jest pewien, czy wolno mu mówić."}], "5": [{"kto": "Elias, numerek 1", "tekst": "Elias przyniósł gazetę. Na trzeciej stronie apel o Maję Doyle: trzydzieści cztery lata, krótkie czarne włosy, płaszcz z za długimi rękawami. „Taka młoda. Zgubiona.” Zapytał o oprawkę. Nie było. Gazeta została na ladzie."}], "6": [{"kto": "Elias, numerek 1", "tekst": "Elias zapytał o oprawkę i dodał, że poprzedni pracownik zawsze przedstawiał się z imienia. Nikt mu jeszcze nie powiedział, jak nazywa się osoba, która teraz siedzi za szybą."}], "7": [{"kto": "Elias, numerek 1", "tekst": "Elias: „On wiedział, że nie będzie. Mówił: jeszcze nie, panie Eliasie. A potem przestał mówić.” Wziął numerek i wyszedł wolno."}], "8": [{"kto": "Elias, numerek 1", "tekst": "Elias zostawił papierowy woreczek z dwoma ciastkami z cukierni obok. „To nie łapówka. To za nocne.” Zapytał o oprawkę. Nie było."}], "9": [{"kto": "Elias, numerek 1", "tekst": "Elias poprosił, żeby oprawkę, jeśli się znajdzie, trzymać osobno. „Gdyby ktoś przyszedł po nią z papierkiem od innego pracownika, proszę nie wierzyć.”"}], "10": [{"kto": "Elias, numerek 1", "tekst": "Elias: „Pytam, bo on mi oddał pieniądze za oprawkę. Nie chciałem ich. Leżą u mnie w kopercie. Jak oprawka się znajdzie, oddam kopertę.” Numerek złożył w prostokąt bardzo ciasny."}]};window.LANG={"title": "OKIENKO", "sub": "Nocna zmiana w biurze rzeczy znalezionych. Tydzień pierwszy.", "start": "Zacznij zmianę", "settings": "Ustawienia", "close": "Zamknij", "day": "Dzień", "delivery": "Tramwaj zostawił skrzynki. Czasu starcza, żeby zajrzeć tylko do jednej rzeczy.", "look": "Zajrzyj", "skip": "Nie zaglądam, otwieram okienko", "line": "Linia", "inspect_hint": "Przeszukaj rzecz. Kliknij to, co nie pasuje.", "found": "Wiesz coś, czego nie powinieneś.", "open": "Otwórz okienko", "nothing": "Zwykła rzecz. Czasem parasol jest po prostu parasolem.", "knock": "Ktoś puka w szybę.", "let_in": "Odsuń zasłonkę", "know": "wiesz ze środka", "turn": "Odwróć się do magazynu", "search": "Znajdź: ", "search_p": "Wybierz skrzynię wg linii, potem przekopuj. Kliknij rzecz, którą bierzesz.", "wrong": "To nie to.", "wrong_line": "Tu tej rzeczy nie ma. Spróbuj inną linię.", "decide": "Rzecz leży na ladzie. Przeciągnij ją albo wybierz.", "wydaj": "Wydaj: przez okienko", "odmow": "Odmów: do skrzyni", "zatrzymaj": "Zatrzymaj: na półkę", "zadzwon": "Zadzwoń po dyżurnego", "next": "Dalej", "evening": "Świt. Poczta na ladzie.", "nomail": "Dziś nikt nie napisał.", "week_h": "Sobota. Rozliczenie.", "pay": "Wypłata", "rent": "Czynsz", "balance": "Zostaje", "drawer": "W szufladzie leży klucz bez zamka. Poprzednik nie zabrał wszystkiego.", "again": "Zacznij od nowa", "next_day": "Następny dzień", "dollar": "$", "vol_master": "Głośność ogólna", "vol_music": "Muzyka", "vol_amb": "Ambient", "vol_sfx": "Efekty", "vol_voice": "Głosy", "reduce": "Ogranicz błyski i wstrząsy", "end": "Koniec dostępnych dni. Dalej: dni, które jeszcze piszemy.", "storm": "Burza. Grom zrzucił skrzynie z półki: rzeczy leżą w innych skrzyniach niż zapisano.", "up_h": "Ulepszenie biura (jedno na sobotę)", "up_none": "Nic nie kupuję", "up_lampa": "Wymień lampę (mruganie ustaje, w biurze robi się nudno)", "up_drzwi": "Uszczelnij drzwi (deszcz za szybą ciszej)", "up_regal": "Dołóż regał (mniej rzeczy w skrzyniach)", "owned": "kupione", "week2": "Następny tydzień", "rent2": "Czynsz za tydzień", "end_zag_A": "Przychodzi pocztówka bez nadawcy z jednym słowem: „Dziękuję”. Evan dostaje suknię. To cała odpowiedź, jaką dostaje. Noah zamyka zgłoszenie.", "end_zag_B": "Noah potwierdza, że Maya jest bezpieczna, i zamyka zgłoszenie. Lena kładzie na ladzie jeden klucz, ten od mieszkania, które Maya zostawiła, i pyta, czy ktoś kiedyś po niego przyjdzie.", "end_zag_C": "Maya przychodzi już tylko po walizkę, bez rozmów, i wyjeżdża na własnych warunkach. Evan wynajmuje detektywa. Lena stoi przy okienku bez Mai i pyta, czy coś zostało po jej siostrze. Gracz wie, że zostało wszystko.", "end_skr_A": "Nora odbiera komplet. Okoye nie płacą drugi raz, a Iris podpisuje rozliczenie i oddaje 6 800 $. Grace Okoye w szpitalnym fartuchu kładzie na ladzie pączek w papierze: „Z dyżuru.”", "end_skr_A2": "Nora ma papiery, ale Iris kwestionuje ich autentyczność i sprawa idzie do sądu poza tą nocą. Grace Okoye kładzie na ladzie pączek w papierze: „Z dyżuru.” Nie wie jeszcze, czy zapłaci drugi raz.", "end_skr_B": "Victor zamyka obieg paczek, przyjmuje oryginały do audytu i zajmuje 6 800 $ jako dowód. Ludzie z żetonów są w aktach. Przychodzi zimny list z Urzędu, a w kolejnym wierszu nazwisko, które znasz z twarzy.", "end_skr_C": "Iris zabiera paczkę, oryginały i 6 800 $. Nora ma kopię jednej wpłaty, resztę będzie musiała odtworzyć. Kamienica o świcie, ekipa rozbiórki. Iris nie ma jej w oknie.", "end_pop_A": "Sam podpisuje zeznanie, Victor dopisuje własny podpis sprzed pięciu tygodni i wycofuje wpis obciążający Sama. Sam wychodzi. Elias siada na krześle poczekalni po raz pierwszy, odkąd pamięta, i czeka na tramwaj, jakby nigdzie się nie spieszył.", "end_pop_B": "Sam odbiera swoje rzeczy i wychodzi, nie odwracając się. W protokole zostaje niedobór. Wyjaśnienie krąży tylko między osobami, które zgodziły się mówić.", "end_pop_C": "Sam, wystawiony, dostaje od Iris pusty bilet bez numeru i znika. Zostawia u Very kopertę z 85 $ dla Eliasa. Elias odmawia jej przyjęcia i składa numerek w najciaśniejszy prostokąt, jaki widziałeś.", "ep_nowysam": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy spakowane w pudełku. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_nowysam_tear": "Victor zapisuje niedobór na twojej zmianie. Wypowiedzenie, rzeczy w pudełku. Wyrwana strona leży już gdzie indziej. Następnego wieczoru przychodzi nowy pracownik i pyta o brakującą stronę.", "ep_referent": "Umowa przedłużona, awans na starszego referenta, wypłata z premią. Zostajesz w okienku.", "ep_referent_tear": "Umowa przedłużona, awans na starszego referenta. W księdze brakuje twojej strony i nikt o nią nie pyta. Zostajesz w okienku jako następny przechowawca.", "ep_zostajesz": "Czynsz zapłacony, umowa przedłużona. Nikt tego nie świętuje.", "ep_zostajesz_tear": "Czynsz zapłacony, umowa przedłużona. W księdze brakuje twojej strony, tak jak po poprzedniku. Jesteś następnym przechowawcą.", "elias_A": "„Czy ktoś jeszcze czeka?”", "elias_B": "„Do jutra.”", "elias_C": "(milczy i kładzie numerek na ladzie)", "elias_N": "„Czy Sam już był?” (do tego, kto siedzi w okienku jutro)", "ledger_h": "Księga wydań leży otwarta na twojej ostatniej stronie.", "ledger_none": "Nic nie ruszam", "ledger_fix": "Dopisz sprostowanie", "ledger_tear": "Wyrwij stronę", "urzad": "Urząd", "ludzie": "Ludzie", "debt": "Tydzień zamknięty z długiem.", "final_h": "Koniec zmiany. Dzień 25.", "th_zag": "Zaginiona", "th_skr": "Skrytka", "th_pop": "Poprzednik", "you": "Ty", "elias": "Ostatnie pytanie Eliasa", "eve_note": "Poza okienkiem", "soon": "Dalej: dni, które jeszcze piszemy."};